def set_run_font(run, name="Times New Roman", size=12, bold=False, italic=False, color=None):
    run.font.name = name
    run._element.rPr.rFonts.set(qn("w:ascii"), name)
    run._element.rPr.rFonts.set(qn("w:hAnsi"), name)
    run.font.size = Pt(size)
    run.font.bold = bold
    run.font.italic = italic
    if color is not None:
        run.font.color.rgb = RGBColor(*color)
    return None


def add_text(paragraph, text, **kwargs):
    run = paragraph.add_run(text)
    set_run_font(run, **kwargs)
    return run


def body(doc, text, first_line=True):
    paragraph = doc.add_paragraph()
    paragraph.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    paragraph.paragraph_format.space_after = Pt(8)
    paragraph.paragraph_format.space_before = Pt(0)
    paragraph.paragraph_format.line_spacing = 1.15
    if first_line:
        paragraph.paragraph_format.first_line_indent = Cm(0.75)
    add_text(paragraph, text)
    return paragraph


def highlight(doc, text):
    paragraph = doc.add_paragraph()
    paragraph.alignment = WD_ALIGN_PARAGRAPH.LEFT
    paragraph.paragraph_format.space_after = Pt(2)
    paragraph.paragraph_format.space_before = Pt(0)
    paragraph.paragraph_format.line_spacing = 1.15
    paragraph.paragraph_format.left_indent = Cm(0.75)
    paragraph.paragraph_format.first_line_indent = Cm(-0.4)
    add_text(paragraph, text)
    return paragraph


def heading(doc, text, level):
    paragraph = doc.add_heading(text, level=level)
    for run in paragraph.runs:
        set_run_font(
            run,
            size=14 if level == 1 else 12,
            bold=True,
            color=(0, 0, 0),
        )
    paragraph.paragraph_format.space_before = Pt(12)
    paragraph.paragraph_format.space_after = Pt(6)
    return paragraph


def equation(doc, text):
    paragraph = doc.add_paragraph()
    paragraph.alignment = WD_ALIGN_PARAGRAPH.CENTER
    paragraph.paragraph_format.space_before = Pt(2)
    paragraph.paragraph_format.space_after = Pt(2)
    add_text(paragraph, text, italic=True)
    return paragraph


def caption(doc, text):
    paragraph = doc.add_paragraph()
    paragraph.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    paragraph.paragraph_format.space_before = Pt(2)
    paragraph.paragraph_format.space_after = Pt(10)
    paragraph.paragraph_format.line_spacing = 1.0
    add_text(paragraph, text, size=10)
    return paragraph


def shade(cell, hex_color):
    tc_pr = cell._tc.get_or_add_tcPr()
    shd = OxmlElement("w:shd")
    shd.set(qn("w:val"), "clear")
    shd.set(qn("w:color"), "auto")
    shd.set(qn("w:fill"), hex_color)
    tc_pr.append(shd)


def add_table(doc, title, headers, rows):
    caption(doc, title)
    table = doc.add_table(rows=1, cols=len(headers))
    table.style = "Table Grid"
    for index, header in enumerate(headers):
        cell = table.rows[0].cells[index]
        cell.text = ""
        paragraph = cell.paragraphs[0]
        add_text(paragraph, header, size=9, bold=True, color=(255, 255, 255))
        shade(cell, "1F4E79")
    for row in rows:
        cells = table.add_row().cells
        for index, value in enumerate(row):
            cells[index].text = ""
            add_text(cells[index].paragraphs[0], str(value), size=9)
    doc.add_paragraph()
    return table


def add_figure(doc, path, text):
    if path.is_file():
        paragraph = doc.add_paragraph()
        paragraph.alignment = WD_ALIGN_PARAGRAPH.CENTER
        run = paragraph.add_run()
        image = Image.open(path).convert("RGBA")
        plate = Image.new("RGB", image.size, (255, 255, 255))
        plate.paste(image, mask=image.split()[-1])
        buffer = BytesIO()
        plate.save(buffer, format="PNG")
        buffer.seek(0)
        run.add_picture(buffer, width=Cm(15.5))
    else:
        body(doc, f"[Figure file not found: {path}]", first_line=False)
    caption(doc, text)


def reference(doc, text):
    paragraph = doc.add_paragraph()
    paragraph.paragraph_format.left_indent = Cm(0.75)
    paragraph.paragraph_format.first_line_indent = Cm(-0.75)
    paragraph.paragraph_format.space_after = Pt(4)
    paragraph.paragraph_format.line_spacing = 1.0
    paragraph.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    add_text(paragraph, text, size=11)
    return paragraph


def footer(section):
    paragraph = section.footer.paragraphs[0]
    paragraph.alignment = WD_ALIGN_PARAGRAPH.CENTER
    add_text(
        paragraph,
        "Tiwari and Guru — Tilaiya monthly soil loss and sediment delivery",
        size=9,
        italic=True,
    )



def build():
    doc = Document()
    section = doc.sections[0]
    section.top_margin = Cm(2.4)
    section.bottom_margin = Cm(2.4)
    section.left_margin = Cm(2.5)
    section.right_margin = Cm(2.5)
    section.page_width = Cm(21.0)
    section.page_height = Cm(29.7)
    footer(section)
    normal = doc.styles['Normal']
    normal.font.name = 'Times New Roman'
    normal.font.size = Pt(12)
    title = doc.add_paragraph()
    title.alignment = WD_ALIGN_PARAGRAPH.CENTER
    add_text(title, 'Spatiotemporal Soil Erosion Dynamics and Sediment Connectivity in a Data-Scarce Monsoon Catchment: An Integrated Framework Coupling Sentinel-1 SAR Time-Series, Stacking Ensembles, and Explainable AI', size=14, bold=True)
    authors = doc.add_paragraph()
    authors.alignment = WD_ALIGN_PARAGRAPH.CENTER
    add_text(authors, 'Mukesh Kumar Tiwari', size=12, bold=True)
    add_text(authors, ' a,*', size=12)
    add_text(authors, ', Prabhat Kumar Guru', size=12, bold=True)
    add_text(authors, ' b', size=12)
    for line in ('a School of Natural Resource Management, ICAR–Indian Agricultural Research Institute, Jharkhand, Gauria Karma, Hazaribagh 825405, Jharkhand, India', 'b School of Natural Resource Management, ICAR–Indian Agricultural Research Institute, Jharkhand, Gauria Karma, Hazaribagh 825405, Jharkhand, India', '* Corresponding author. E-mail: Mukesh.tiwari1@icar.org.in; Tiwari.iitkgp@gmail.com. ORCID: 0000-0003-0385-4426.', 'E-mail: prabhatkumarguru@gmail.com.'):
        line_p = doc.add_paragraph()
        line_p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        add_text(line_p, line, size=10, italic=True)
    heading(doc, 'Abstract', 1)
    body(doc, 'In data-scarce monsoon headwaters, conventional soil erosion models frequently assert false deterministic precision while masking order-of-magnitude parameter uncertainties. Here, we present an integrated spatiotemporal framework that decouples seasonal erosion timing from volumetric load sizing across the 715 km² headwater catchment of the Tilaiya Reservoir, eastern India. Erosivity choices move the 2025 annual mean by about a factor of ten, and cover choices move it by about a factor of five. The Central Water Commission live-storage loss of 1.01 million m³ yr⁻¹ fixes the size used for planning: at a Vanoni delivery ratio of 0.20 the gross rate consistent with that loss is 51–75 t ha⁻¹ yr⁻¹. Rainfall erosivity uses the corrected Arnoldus equation on the India Meteorological Department 0.25° grid. Cover is estimated from Sentinel-2 SAVI, with July and August interpolated from June and September because cloud cover leaves too few clear monsoon scenes. Continuous Copernicus GLO-30 multiple-flow routing (Desmet–Govers) reduces the legacy integer-metre zero class from 44.36 percent of cells to 1.0 percent, and yields a hillslope detachment surface with a median of 72 t ha⁻¹ yr⁻¹, which lies in the 51–75 t ha⁻¹ yr⁻¹ reservoir planning band, and a mean of 140 t ha⁻¹ yr⁻¹. The mean stays outside that band, with 41 percent of the map still above 100. Annual load remains conditioned by elevation continuity and by the cover formulation. The monthly series holds one slope-length grid and isolates the intra-annual pulse: July accounts for approximately half the linear-cover annual detachment. Linear cover, 136 t ha⁻¹ yr⁻¹, is the uncalibrated upper bound, and the European exponential of NDVI, 27.6 t ha⁻¹ yr⁻¹, is the lower bound. On a 3,809-point holdout, a multilayer perceptron recovers the multiplicative tail of this RUSLE surface (R² = 0.920), whereas XGBoost and Random Forest remain at 0.451 and 0.443.', first_line=False)
    body(doc, 'Keywords: ungauged watershed; monthly soil loss; RUSLE; rainfall erosivity; land cover; Tilaiya Reservoir', first_line=False)
    heading(doc, 'Highlights', 1)
    for item in (
        '2A219 is ungauged, so 2025 soil loss is a set of RUSLE scenarios.',
        'Erosivity varies about 10× and cover about 5× in these scenarios.',
        'The India-grid value 772 is a low floor; Jharkhand averages 1,198.',
        'Linear cover, 136, is the upper bound; exponential cover is the lower.',
        'Multiple-flow Copernicus LS: 1% zero, median 72.',
        'Planning target from live-storage loss: 51–75 t ha⁻¹ yr⁻¹.',
        'Vegetation is 40% of area and carries 60% of linear-cover loss.',
        'The lookup puts 23% of the loss on barren land, 2.2% of the area.',
    ):
        highlight(doc, '• ' + item)
    heading(doc, '1. Introduction', 1)
    body(doc, 'A single RUSLE map of an ungauged basin reads as one determined rate. The factor choices behind that rate do not. In this headwater, replacing the erosivity estimate moves the annual soil-loss mean by about a factor of ten, and replacing the cover equation moves it by about a factor of five. An uncalibrated number therefore conceals the range a manager would actually have to plan for. The same pattern is already in the literature. Most maps of water erosion use the Universal Soil Loss Equation or its revision (Wischmeier and Smith, 1978; Renard et al., 1997). Alewell et al. (2019) found such studies in 109 countries and listed four recurring limits: the equation estimates hillslope detachment, satellite data are finer than the original field plots, monitoring is scarce, and uncertainty is often left out. Borrelli et al. (2021) reviewed 3,030 modelling records from 1994 to 2017 and found that about 41 percent used the (R)USLE family, with India among six countries that together account for about half of the applications. Of 100 USLE studies in India, nearly all mis-specified at least one factor, errors in the rainfall factor were common, and most of the studies were in eastern India, the region drained by the Damodar and its Barakar tributary (Majhi et al., 2021). Bhattacharyya et al. (2015) reported 147 million hectares of degraded land, of which 94 million hectares are affected by water erosion. This paper maps January–December 2025 in sub-watershed 2A219 as an explicit set of scenarios, and it separates the month of erosion from the size of the annual load.')
    body(doc, 'Monthly satellite records can time that erosion even while the annual total remains sensitive to the factor definitions. In the linear-cover series, July contains about half of the annual mean. Cover and tillage that are in place before July therefore address the month that carries half the year’s detachment. Where rainfall intensity is measured, monthly erosivity shows the same kind of seasonal peak, and in Europe that peak is several times the winter value (Ballabio et al., 2017). For India, Tiwari et al. (2015) mapped long-term erosivity from monthly rainfall at 52 stations and Pai et al. (2014) provide daily rainfall on a 0.25° grid. The 2025 monthly totals from that grid are converted to erosivity with the Modified Fournier index and the equations of Arnoldus (1977, 1980) and Renard and Freimund (1994). Chen et al. (2023) showed that these equations are often copied with the wrong coefficients, so the equation used here is stated in full. Cover is the other factor that changes through the year. A satellite C factor depends on the vegetation index and on the coefficient that converts the index to C (Huete, 1988; Benavidez et al., 2018; Phinzi and Ngetar, 2019), and optical indices need cloud-free images, which are hardest to obtain in the wet months. Sentinel-1 remains available through cloud (Torres et al., 2012), and VV and VH can be combined into a radar vegetation index (Kim and van Zyl, 2009). In the 2025 record, July has two Sentinel-2 scenes and nine Sentinel-1 scenes. Radar cover was calculated for July and August and was not the reported cover. Reported July and August cover is interpolated from June and September because monsoon optical scenes are cloudy. A radar-to-optical fit outside July and August was inspected and not used for the reported cover.')
    body(doc, 'Tilaiya Dam, on the Barakar River, was inaugurated on 21 February 1953 under the Damodar Valley Corporation, which gives the dam catchment as 984 km². The Key Biodiversity Area factsheet gives the same area, 98,420 ha (Damodar Valley Corporation, n.d.; Key Biodiversity Areas, n.d.). The reason for mapping erosion in sub-watershed 2A219 is the storage of that reservoir. Central Water Commission (2021) reported a 2021 live capacity of 131.235 million m³ against an original 199.89 million m³, a loss of 68.655 million m³ over 68 years, about 1.01 million m³ yr⁻¹. That loss is the benchmark the hillslope scenarios are read against. At a Vanoni delivery ratio of 0.20 it implies a gross detachment of 51–75 t ha⁻¹ yr⁻¹ on the official catchment. The scenarios are read against that band. The local sediment studies are set out in Section 2.')
    body(doc, 'These studies answer different questions. Annual maps average the monsoon into one value, and SWAT estimates how much sediment reaches the dam without showing which month or which slope produced it. Some of the soil detached on a slope is stored along the path, so the load leaving the catchment is a separate quantity (Walling, 1983; Kinnell, 2008). Gross soil-loss maps and measured yields are therefore kept separate (de Vente et al., 2013; Alewell et al., 2019). Connectivity indices can link the two. Most of them describe the terrain and the flow paths. Seasonal sediment movement is estimated separately (Borselli et al., 2008; Vigiak et al., 2012; Hamel et al., 2015; Heckmann et al., 2018). Biswas and Pani (2015) mapped the Barakar and left delivery aside because sediment measurements were lacking. Sardar et al. (2014) and Dutta et al. (2017) routed sediment to Tilaiya in SWAT at the sub-watershed scale. This study maps one year in that headwater as a bounded set of hillslope scenarios. Sub-watershed 2A219 has no sediment gauge. In headwater catchments of the Chota Nagpur plateau that absence is the usual condition, and a set of explicit scenarios is a clearer basis for management than one uncalibrated rate. The 2025 maps are calculated from rainfall, satellite cover, soil grids, and elevation. They describe hillslope detachment. The load that reached the dam is addressed by comparing those scenarios with the live-storage loss.')
    body(doc, 'The calculations use 2025 data for sub-watershed 2A219, an area of 715 km², or 73 percent of the 984 km² dam catchment. Totals are reported for this 715 km² mask. Monthly soil loss is the product of erosivity, erodibility, the LS factor, cover and support practice, and the annual total uses only pixels that are valid in all twelve months. In the reported maps, July and August cover is interpolated from June and September. Radar cover is reported as a sensitivity test. Scenario means are set beside the live-storage loss of about 1.01 million m³ yr⁻¹ (Central Water Commission, 2021). A stacking model in the supplement recovers the annual RUSLE surface from its own factors. That recovery is not a test against sediment (Lundberg and Lee, 2017; Roberts et al., 2017; Ploton et al., 2020; Mallick et al., 2025).')
    body(doc, 'The paper has three aims. The first is to show how far the annual rate moves when erosivity, cover, and slope length are each replaced by a documented alternative. The second is to time the erosion: with one slope-length grid held through the year, July contains about half of the linear-cover annual mean, which is the month cover and tillage have to meet. The third is to anchor the scenarios to the reservoir. The live-storage loss of about 1.01 million m³ yr⁻¹, read at a Vanoni delivery ratio of 0.20, sets the planning band at 51–75 t ha⁻¹ yr⁻¹. Inside that comparison the terrain result is the unfilled Copernicus GLO-30 multiple-flow grid, with exact zeros on 1.0 percent of cells, a median of 72 t ha⁻¹ yr⁻¹, and a mean of 140. Routing uses the calibrated Borselli map in Figure 2, with the threshold at −6.29 so the unweighted mean delivery ratio is 0.20. A multilayer perceptron on the 3,809-point holdout (R² = 0.920) diagnoses the multiplicative RUSLE surface. It is not a test against measured sediment. A sediment budget fitted to the reservoir would still require storm erosivity and a shoreline inside the mask.')
    heading(doc, '2. Literature review and research gaps', 1)
    heading(doc, '2.1 Annual maps and reservoir inflow in the Damodar headwaters', 2)
    body(doc, 'Section 1 gives the national and global context, but an annual mean still needs care. García-Ruiz et al. (2015) compiled field measurements, and Borrelli et al. (2021) report median gross rates of 9.6 t ha⁻¹ yr⁻¹ for the USLE and 12.6 t ha⁻¹ yr⁻¹ for the RUSLE, with a median of about 6.4 t ha⁻¹ yr⁻¹ for SWAT applications classed as net erosion. A value in that range is a modelled soil-loss rate. Reservoir siltation is reported separately. Majhi et al. (2021) also found that many Indian USLE studies are described too briefly to repeat, and they warned against mixing gross maps with measured yields. The Damodar headwaters contain both kinds of result.')
    body(doc, 'On the mapping side, Pandey et al. (2007) applied the USLE on 200 m cells in the Karso watershed of Hazaribagh, within the Barakar system, and compared the grid sediment yield with observations, with a deviation of 1.37 to 13.85 percent. That remains the nearby example of a USLE sediment yield checked against a measurement. Biswas and Pani (2015) mapped annual RUSLE soil loss for the whole Barakar basin and found that rates above 100 t ha⁻¹ yr⁻¹ covered 0.08 percent of the basin, with the high values following the slope-length and erodibility factors. They discussed reservoir capacity using Damodar Valley Corporation surveys of Maithon and named Tilaiya as the upstream impoundment. Delivery remained outside that study. Ghosh et al. (2025) repeated the annual calculation for the whole Damodar basin in Google Earth Engine and reported mean soil loss of 12.86 t ha⁻¹ yr⁻¹ in 2017 and 12.06 t ha⁻¹ yr⁻¹ in 2024, attributing the change to rainfall. Field observations at that basin scale were unavailable.')
    body(doc, 'At the reservoir, Sardar et al. (2014) calibrated SWAT to monthly inflow at Tilaiya and Maithon and to runoff and sediment at Banha and Karso, with agreement within 10 percent. The publisher abstract prints a Tilaiya sedimentation rate as 0.76 mm3/year. The typeset PDF was unavailable, so that figure is not used as a benchmark. Central Water Commission (2021), publication CWC/2021/147, surveyed live storage from satellite data and reported a 2021 live capacity of 131.235 million m³ at full reservoir level against an original 199.89 million m³, a loss of 68.655 million m³ (34.3 percent) over 68 years, or about 1.01 million m³ yr⁻¹. The numerical comparison uses that survey. The critical areas were compared with the sediment-yield-index map of the Damodar Valley Corporation at Hazaribagh. Dutta et al. (2017) calibrated SWAT to Tilaiya streamflow for 1991–1995, checked it for 1996–2000, and estimated that dead storage would fill in 89 years from the year 2000. These are reservoir-life estimates from a gauged model. A hillslope map can be set beside these reservoir-life estimates. Karso and Banha are gauged watersheds. Sub-watershed 2A219, the mask used here, has no sediment station, so the 2025 maps are soil-loss scenarios from rainfall, satellite cover, soil grids, and elevation.')
    body(doc, 'A further annual total for the whole basin would leave the monthly pattern unresolved. The published maps average the monsoon into one number. The SWAT studies estimate the sediment at the dam. For 2025, this paper maps the month of the hillslope estimate on the 715 km² mask. The annual load is left as a set of scenarios.')
    heading(doc, '2.2 Monthly erosivity without storm intensity', 2)
    body(doc, 'In the RUSLE, the rainfall factor is the annual sum of storm EI30. EI30 requires the rainfall intensity during each storm (Wischmeier and Smith, 1978; Renard et al., 1997). Where intensity data exist, monthly erosivity shows the period in which cover and tillage ought to be applied. Ballabio et al. (2017) mapped this quantity for Europe from sub-hourly rainfall. The seasonal peak was several times the winter value, so that an annual R factor conceals the months that matter most. Tiwari et al. (2015) prepared a long-term erosivity map for India from 101 years of monthly rainfall at 52 stations. That map is a national average. For 2025, this study uses monthly totals on the 0.25° grid of the India Meteorological Department.')
    body(doc, 'The IMD grid does provide monthly totals. These can be converted to an R value with the Modified Fournier index, MFI = P² / Pannual, and the regressions of Arnoldus (1977, 1980) and Renard and Freimund (1994) (Fournier, 1960). The choice of equation affects the result. Majhi et al. (2021) found the R factor to be among the terms most often specified incorrectly. Chen et al. (2023) showed that one empirical erosivity equation has been copied with the wrong coefficients in many countries. A monthly map should therefore state its coefficients.')
    body(doc, 'The reported maps use the corrected Arnoldus (1977) equation in the form given by Chen et al. (2023). That equation was estimated for Morocco and is applied here with the published coefficients. An earlier monthly power function used the coefficients 1.8219 and 1.211. No paper giving that pair was found. The results reported here use the corrected Arnoldus equation. The annual total is divided among the months in proportion to the square of monthly rainfall. Cell 1 still attains its peak in June. The other four cells attain their peak in July. On the wettest cell, July holds 0.57 of the annual total. Renard and Freimund (1994) provide a second annual total, fitted in the United States. That total is reported for comparison. The monthly maps use the Arnoldus equation.')
    heading(doc, '2.3 Cover when the optical record fails', 2)
    body(doc, 'The cover factor is what allows a monthly map to change through the year. Phinzi and Ngetar (2019) reviewed catchment studies that estimate this factor from remote sensing, and they concluded that the map is only as reliable as that step. Benavidez et al. (2018) made the same point for vegetation-index equations carried from one region to another. The index measures the canopy. The coefficient that converts it to C remains an assumption unless it is fitted locally. Optical indices are the usual source (Huete, 1988), and they require a clear view.')
    body(doc, 'In a monsoon headwater, cloud cover is greatest in the months of highest erosivity. Sentinel-1 C-band backscatter remains available in those months (Torres et al., 2012), and a radar vegetation index can be calculated from VV and VH (Kim and van Zyl, 2009). Each month states which sensor supplies the cover factor. Radar cover was calculated for July and August. Because the radar index diverges from the optical index, the reported maps use cover interpolated from the optical factors of June and September. The coefficient 1.18 is an adopted value.')
    heading(doc, '2.4 A stack that recovers a RUSLE map', 2)
    body(doc, 'Mallick et al. (2025) trained a stacking model on RUSLE classes in the Kangsabati basin and explained it with SHAP. SHAP is applied to one learner, because a stack contains several models (Lundberg and Lee, 2017). Roberts et al. (2017) and Ploton et al. (2020) showed that a random split of nearby points underestimates the error of a map. A high score can mean only that the model has reconstructed the LS factor, the cover and the erodibility. Section S1 reports how closely the stack recovers the RUSLE surface at Tilaiya.')
    heading(doc, '2.5 From detached soil to delivered sediment', 2)
    body(doc, 'Walling (1983) described the sediment delivery problem. Some detached soil is stored along the path, and the travel distance matters, so hillslope detachment and the load leaving the catchment are separate quantities. Kinnell (2008) made the same point for the USLE. The equation estimates sheet and rill detachment on a slope. Sediment yield needs a second calculation. de Vente et al. (2013) found that gross-erosion maps and measured yields still answer different questions, and Alewell et al. (2019) listed this difference among the main open problems. Heckmann et al. (2018) reviewed the indices used for that second step. Nearly all of them describe the permanent pattern of connectivity. Seasonal sediment movement is a separate question.')
    body(doc, 'Borselli et al. (2008) defined the index of connectivity as the log ratio of an upslope component to a downslope path cost, and Vigiak et al. (2012) compared that family of metrics with hillslope delivery. Hamel et al. (2015) put a sigmoid on the index inside the InVEST sediment model, with a maximum delivery ratio, a threshold, and a slope parameter that are usually taken from the literature. Biswas and Pani (2015) stopped before this step in the Barakar. The sediment data available to them stopped short of a delivery ratio. Sardar et al. (2014) and Dutta et al. (2017) carried sediment to Tilaiya inside SWAT, at the scale of sub-watersheds and reservoir inflow, without a 12.5 m connectivity surface.')
    body(doc, 'With the layers assembled here, a Borselli grid was calculated. The routing map in this paper sets the threshold at −6.29, so the unweighted mean delivery ratio is 0.20, the Vanoni value for the official catchment (Section 5.6 and Figure 2). The literature default of 0.5 gives a mean of 0.00105 on this mask. The area curves in Section 6.4 remain the lumped check on that map.')
    heading(doc, '2.6 What the present study tests', 2)
    body(doc, 'The present study tests the 2025 soil-loss scenarios for ungauged sub-watershed 2A219. The first is a monthly soil-loss map on the 715 km² mask, using the corrected Arnoldus equation. The second compares cover and the practice factor. The third sets those means beside the live-storage yield. The distributed routing map is the Borselli grid at IC₀ = −6.29, and the area curves remain the lumped check. Section 6.6 compares the perceptron with the tree members on the holdout. The full tables remain in the supplement.')
    heading(doc, '3. Study area', 1)
    body(doc, 'Sub-watershed 2A219 forms the headwater of Tilaiya Reservoir on the Chota Nagpur plateau in eastern India. Inside that boundary, 4,576,196 cells of 12.5 m cover 715.0 km². Damodar Valley Corporation lists the catchment of Tilaiya Dam as 984 km², and the Key Biodiversity Area factsheet for the reservoir gives the same drainage area, 98,420 ha (Damodar Valley Corporation, n.d.; Key Biodiversity Areas, n.d.). This mask is 73 percent of that official catchment, so soil-loss totals stay on the 715 km² mask and are not scaled to 984 km²; the remaining 269 km² stay outside the totals. Coordinates run from approximately 24.09° N to 24.39° N and from 85.14° E to 85.49° E, in WGS 84 / UTM zone 45N, and drainage reaches the Tilaiya impoundment on the Barakar, inaugurated on 21 February 1953. On this plateau the ALOS PALSAR elevations run from 312 to 670 m and are stored in whole metres, so broad flats alternate with steeper valley sides, and those equal-metre flats are the cells on which slope length is later zero. SoilGrids representations of texture and organic carbon (Poggio et al., 2021), resampled to the 12.5 m grid, supply the soils used here. Cultivation, fallow, and woody vegetation typical of this plateau share the land cover. Mapping records that mixture as one vegetation class (Section 5.3), while the support-practice factor retains the five-class pattern as a static grid. Figure 1 shows the analysis mask.')
    add_figure(doc, ((FIGURES / 'maps') / 'Tilaiya_2A219_study_area.png'), 'Figure 1. Study area, sub-watershed 2A219 (715 km²). This polygon is the boundary used for soil loss and the reported areas. The frame is WGS 84 / UTM zone 45N.')
    body(doc, 'Rainfall is monsoonal. In 2025 the five 0.25° cells that intersect the watershed received 1,090–1,443 mm, and June to October supplied almost the whole of the annual total, while January, February, and December were dry on every cell. Sub-watershed 2A219 is ungauged for sediment: no erosion-plot record, sediment-sampling station, or 2025 bathymetric survey is available for this mask, and the records summarized in Section 2 describe other places or other years. Maps for this 715 km² mask are therefore soil-loss scenarios built from rainfall, satellite cover, soil grids, and elevation, with the Commission live-storage loss kept as context for the modelled volumes.')
    heading(doc, '4. Data and multi-sensor processing', 1)
    body(doc, 'All rasters were aligned to one grid: 2,777 columns by 2,677 rows, cell size 12.5 m, upper-left origin 311,579.4375 E, 2,698,245.25 N, EPSG:32645. New rasters use NoData −9999. The digital elevation model uses NoData 32767. A cell area is 156.25 m², or 0.015625 ha. The 12.5 m grid is a common calculation frame. Rainfall and erosivity are constant inside each 0.25° IMD cell (Pai et al., 2014). SoilGrids texture, organic carbon, and the base erodibility derived from them are 250 m information placed on the 12.5 m cells (Poggio et al., 2021). Elevation is a 12.5 m product, but the values used here are stored in whole metres, so flats have no unique slope and the LS factor is exactly zero on those cells. The LS factor, flow direction, and the monthly satellite composites are the layers that can vary from cell to cell. Soil-loss maps at 12.5 m place these mixed-resolution inputs on a fine grid.')
    add_table(doc, 'Table 1. Data used to build the 2025 monthly soil-loss maps.', ['Data', 'Source and resolution', 'Role in the present study'], [['Elevation', 'ALOS PALSAR RTC DEM, 12.5 m (Rosenqvist et al., 2007)', 'Slope, flow paths, hillshade'], ['Rainfall', 'IMD daily grid, 0.25°, 2025 (Pai et al., 2014)', 'Monthly and annual erosivity'], ['Sentinel-2', 'Copernicus optical scenes, 2025, Google Earth Engine', 'SAVI and optical cover'], ['Sentinel-1', 'Copernicus C-band GRD, VV and VH, 2025', 'RVI and the wetness index for Km'], ['Soil', 'SoilGrids 2.0, 250 m (Poggio et al., 2021)', 'Texture, SOC, and base erodibility K'], ['LS, C, P, NDVI, annual A', 'Aligned 12.5 m annual RUSLE layers for this catchment', 'Static factors and the machine-learning target'], ['Land cover', 'LULC_2025_RF_v2, about 10 m, five classes, warped to 12.5 m', 'Class shares and the lookup cover'], ['Watershed', 'Sub-watershed 2A219 boundary', 'Analysis mask and map frame']])
    body(doc, 'Sentinel-2 reflectance was divided by 10,000 before the vegetation index, because the soil-adjustment term is defined on reflectance. Sentinel-1 GRD values were converted from decibels to linear power before the radar vegetation index. Optical scenes are the Copernicus collection COPERNICUS/S2_SR_HARMONIZED (Drusch et al., 2012). A month keeps scenes with cloudy-pixel percentage below 80, and the scene-classification layer then masks classes 3, 8, 9, 10, and 11. The monthly optical image is the median of the remaining pixels. Radar scenes are COPERNICUS/S1_GRD, interferometric wide swath, with both VV and VH (Torres et al., 2012). The monthly radar image is the median of VV and VH in decibels. No orbit-direction split, speckle filter, incidence-angle correction, or additional terrain correction was applied. Scene counts after these filters are given in Table 2. July retains two Sentinel-2 scenes and August retains five, against nine and ten Sentinel-1 scenes in those months.')
    add_table(doc, 'Table 2. Scenes retained in each month of 2025 after filtering.', ['Month', 'Sentinel-2', 'Sentinel-1', 'Month', 'Sentinel-2', 'Sentinel-1'], [['January', '12', '11', 'July', '2', '9'], ['February', '10', '9', 'August', '5', '10'], ['March', '14', '11', 'September', '10', '9'], ['April', '15', '9', 'October', '10', '11'], ['May', '16', '10', 'November', '13', '10'], ['June', '5', '11', 'December', '15', '10']])
    heading(doc, '5. Methods', 1)
    body(doc, 'Soil loss was estimated with the Revised Universal Soil Loss Equation as the product of rainfall erosivity, soil erodibility, slope length and steepness, cover management, and support practice. The product is potential sheet and rill detachment. It is the hillslope source, not the sediment load arriving at Tilaiya Dam. Sub-watershed 2A219 has no sediment gauge, so each substitution of cover, erosivity, or terrain is kept as a named scenario. All layers share a 12.5 m grid. Rainfall is constant inside each 0.25° cell and soil properties come from a grid of about 250 m, so a pixel value places those coarser fields onto the elevation and satellite layers. Sediment delivery is estimated afterwards with a Borselli index of connectivity. The threshold of that index is set so the mean delivery ratio equals the Vanoni value for the official dam catchment, and the Vanoni, USDA, and Boyce area curves are retained as the lumped comparison.')
    heading(doc, '5.1 Monthly rainfall erosivity', 2)
    body(doc, 'Erosivity was calculated for each IMD cell from its own monthly rainfall. The annual value is the corrected Arnoldus (1977) equation, in the form given by Chen et al. (2023):', first_line=False)
    equation(doc, 'R = 17.02 × 10^(1.50 × log₁₀(Σ Pₘ² / P) − 0.8188)')
    equation(doc, 'Rₘ = R × (Pₘ² / Σ Pₘ²)')
    body(doc, 'P and Pₘ are in millimetres. R is in MJ mm ha⁻¹ h⁻¹ yr⁻¹, and Rₘ is the monthly share of that annual total. A dry month has Rₘ = 0, and the twelve monthly values sum to R. The split follows the monthly terms inside the Modified Fournier index (Fournier, 1960; Arnoldus, 1980). Chen et al. (2023) reviewed 125 papers that copied this equation incorrectly. They defend the factor 17.02 as the conversion from U.S. customary units and the intercept −0.8188. The copies that use 1.735, or −0.08188, are the errors in that review. Replacing 17.02 with 1.735 would lower every R value by a factor of 9.8. Arnoldus (1977) estimated the annual equation for Morocco. The monthly factor allocates that annual total in proportion to the square of monthly rainfall. The reported monthly maps use this erosivity and the interpolated July and August cover. The raster arithmetic is described in the repository README. Renard and Freimund (1994) give a second published annual total from the same rainfall. Those equations were fitted in the United States. They are reported in Tables 4 and 8. The monthly maps use the Arnoldus equation.')
    body(doc, 'Two spatial supports were calculated and kept separate. A six-cell mean inside an expanded bounding box totals 1,307 mm in 2025 and is a catchment time series with no map. The maps use the five 0.25° cells whose polygons intersect the watershed. Each 12.5 m pixel receives the value of the IMD cell that covers it. There is no interpolation between cells. The sixth cell, centred at 85.50° E, 24.50° N, falls in the bounding box and lies outside the watershed, so it is excluded.')
    heading(doc, '5.2 Cover management and the within-month stretch of K', 2)
    body(doc, 'The soil-adjusted vegetation index uses the standard soil-adjustment factor L = 0.5 (Huete, 1988):', first_line=False)
    equation(doc, 'SAVI = ((NIR − Red) / (NIR + Red + 0.5)) × 1.5')
    body(doc, 'Red is Sentinel-2 band 4 and NIR is band 8. The dual-polarisation radar vegetation index, after conversion of decibels to linear power, is', first_line=False)
    equation(doc, 'σ⁰ = 10^(dB/10)')
    equation(doc, 'RVI = 4 × VH / (VV + VH)')
    body(doc, 'This is the dual-polarisation form of the radar vegetation index associated with Kim and van Zyl (2009), applied here to the Sentinel-1 VV and VH pair. The same cover equation is used in every month:', first_line=False)
    equation(doc, 'Cₘ = clip(1 − 1.18 × canopy index, 0.001, 1)')
    equation(doc, 'Cₙ = clip(exp(−2 × NDVI / (1 − NDVI)), 0.001, 1)')
    body(doc, 'Reported cover uses SAVI from January to June and from September to December. July and August cover in the reported maps is interpolated from June and September, because monsoon optical scenes are cloudy. Radar cover was calculated for July and August and was not the reported cover. A radar-to-optical fit outside July and August was inspected and not used for the reported cover. Where the radar layers were calculated, RVI is clipped to 0–1 before the equation so that Cₘ stays inside 0.001–1. The equation reaches the floor of 0.001 once the canopy index exceeds (1 − 0.001) / 1.18, about 0.847. June has only five clear optical scenes and remains on SAVI; the interpolation applies to July and August. The coefficient 1.18 is an adopted linear form (Benavidez et al., 2018). The files on disk keep the calculated radar layers for July and August. The SAVI-based factor is retained as Cₘ, optical in every month. Radar cover remains the sensitivity case. A second cover, Cₙ, is the exponential of NDVI published by van der Knijff et al. (2000) for a European soil-erosion assessment. The coefficient 2 belongs to that European calibration and is uncalibrated at Tilaiya. Negative NDVI is treated as bare. July and August NDVI use the same June and September weights, because a clear July NDVI is present on 2.8 percent of the annual pixels. The exponential is applied after that interpolation, so the July value is the exponential of an interpolated index. July mean soil loss is 65.4 t ha⁻¹, about half of the annual mean of 136, and that is the month whose NDVI is interpolated. A Harmonized Landsat and Sentinel-2 composite (Claverie et al., 2018), or a Sentinel-2 composite with a relaxed cloud threshold, would replace the interpolation with observed wet-month NDVI. That composite lies outside the reported cover, so July and August stay on the June–September interpolation. Erosivity-weighted class means of the linear cover and of this exponential were set beside published cover factors (Section 6.4). The reported cover remains the linear SAVI form.')
    body(doc, 'Base erodibility K is the aligned annual K layer. Monthly erodibility raises K where Sentinel-1 VV is high relative to that month’s own distribution, which is the expected direction for a wetter surface. The index is a percentile stretch of Sentinel-1 VV:', first_line=False)
    equation(doc, 'θ = clip((VV − VVₚ₅) / (VVₚ₉₅ − VVₚ₅), 0, 1)')
    equation(doc, 'Kₘ = K × (1 + 0.25 × θ)')
    body(doc, 'On the soil-loss maps the 5th and 95th percentiles are calculated inside the watershed, separately for each month. Because θ is stretched to 0–1 inside every month, a wetter month and a drier month can have the same θ distribution even when their VV levels differ. The point table used for machine learning was built with percentiles of the full monthly raster. A point value of Kₘ can differ from the map pixel at the same location. That difference remains in the point table. The coefficient 0.25 sets the largest monthly increase at 25% of base K. It is a heuristic. In RUSLE, K is a soil property. Kₘ is a within-month rescaling of K. The within-month percentile stretch removes absolute differences in backscatter between months, and the coefficient 0.25 is assumed. The same equation was also evaluated with bounds taken once from the 2025 series: the literal annual minimum and maximum, the pooled 5th and 95th percentiles, and each pixel’s own annual minimum and maximum (Section 6.2). The aligned Sentinel-1 stack is those twelve months. They are the full backscatter series in this study. Section 6.5 repeats the annual sum with erodibility held at base K. The reported maps keep this heuristic in the primary scenario. Sentinel-1 backscatter still carries slope and aspect, because incidence angle and terrain remain in the signal.')
    heading(doc, '5.3 Monthly soil loss', 2)
    body(doc, 'Monthly soil loss multiplies the spatial erosivity raster by the monthly erodibility and cover and by the static LS factor and the support-practice factor. LS here is slope length and steepness together:', first_line=False)
    equation(doc, 'Aₘ = Rₘ × Kₘ × LS × Cₘ × P')
    body(doc, 'Whole-metre elevations set the legacy slope-length grid to zero wherever neighbouring cells share one stored metre. That grid is retained as the baseline product. A D8 reconstruction on that integer-metre surface is the test that locates the zero class. The Copernicus surface is the terrain result of a separate annual experiment. The reconstruction on the integer-metre ALOS DEM is steepest-descent D8 (O’Callaghan and Mark, 1984) with USLE length exponents 0.2, 0.3, 0.4, and 0.5 as slope crosses 1, 3, and 5 percent (Wischmeier and Smith, 1978) and the McCool et al. (1989, 1987) steepness factor, scaled by the median ratio 1.124. Pearson correlation with the legacy grid is 0.771 (Section 6.5). Exact zeros in that reconstruction are equal-metre plateaus, and the legacy grid itself is exactly zero on 44.36 percent of the annual-support pixels. The monthly files on disk keep this legacy slope-length grid. The Moore and Burch (1986) contributing-area form correlates at 0.76. That is the form implemented by Desmet and Govers (1996). Hickey downhill length lies outside this comparison. In the D8 equation, LS is set to zero only where the steepest descent is zero. That test reads the stored whole-metre elevations and applies no depression fill. Flow is steepest-descent D8. Accumulation counts every cell that drains into a cell, including that cell. Upslope length is the accumulation count times 12.5 m, and it is at least one cell. The length exponent is 0.2 below 1 percent slope, 0.3 from 1 percent up to 3 percent, 0.4 from 3 percent up to 5 percent, and 0.5 at 5 percent and above. Steepness is the McCool factor below. The surface scored against the legacy grid is that product multiplied by 1.124. Depression filling by priority-flood is used for the connectivity index in Section 5.6, and it is separate from this LS test. Filling closed pits on the integer-metre DEM would not slope the cells whose neighbours already share one elevation. Copernicus GLO-30, under the same length equation, already lowers the zero share from 44 percent to 1.2 percent and leaves the annual mean at 119, with 35 percent of the area still above 100 (Section 6.5). The corrected terrain grid places Copernicus GLO-30 under multiple-flow contributing area and the Desmet and Govers (1996) factor, LS = 1.4 × (Aₛ / 22.13)^0.4 × (sin β / 0.0896)^1.3. Aₛ is contributing area per unit width. β is the steepest downslope. LS is zero only where every neighbour is level or higher. On the annual support that grid leaves 1.0 percent of cells at zero, with median soil loss 72 and mean 140 (Section 6.5). The 44 percent zero class belongs to the published raster. On the annual support the published LS mean is 1.38 and its median is 0.40. The support-practice grid that enters the monthly product takes three values: 0 on 6.9 percent of the pixels, 0.5 on 51 percent, and 1 on 42 percent, with a mean of 0.68. The land-cover layer is LULC_2025_RF_v2, a five-class unsigned-integer grid at 0.00009° (about 10 m) in geographic coordinates, warped onto this 12.5 m grid. To test the sensitivity of the soil-loss prediction to land-cover class, the five-class map is set beside multi-temporal Sentinel-2 SAVI and beside the exponential of NDVI. Those are the three cover formulations. The class map is the lookup scenario. No separate accuracy score was calculated for the classifier. The aligned copy is floating point, so each pixel was read as its nearest class code. On the annual support the classes are 51 percent cropland, 40 percent vegetation, 4.4 percent built-up, 2.4 percent water, and 2.2 percent barren land. Vegetation lumps forest, plantation, scrub, and fallow. Cropland carries P = 0.5 on 94 percent of its pixels, vegetation carries P = 1 on 93 percent, built-up carries P = 0 on 91 percent, and barren land carries P = 1 on 98 percent. The 0/0.5/1 grid is that class recode. A land-cover attribute table lists a second set of numbers for the same classes: built-up 0.002, cropland 0.28, vegetation 0.005, water 0, and barren land 1. Those numbers lie far below the linear cover on the vegetated classes, and Section 6.4 applies them as a third cover scenario.')
    equation(doc, 'LS = (λ / 22.13)^m × S')
    equation(doc, 'S = 10.8 sin β + 0.03    (slope below 9 percent)')
    equation(doc, 'S = 16.8 sin β − 0.50    (slope of 9 percent and above)')
    body(doc, 'A pixel is NoData when K, LS, P, Cₘ, VV, or Rₘ is missing, or when the product is negative. The annual map is the sum of the twelve months only where all twelve months are valid. A pixel that lacks any month stays out of the annual sum. About 30,208 watershed pixels lack K, LS, or P in every month. June has 111,194 missing pixels and September 347,762, from gaps in the monthly satellite layers. Monthly means use each month’s own valid pixels. The annual mean and the gross erosion total use only the twelve-month intersection, and the June–July comparison in Section 6.2 uses that same common support. Figure 16 and Table 16 compare the pixels inside and outside that twelve-month support by elevation, D8 slope, October NDVI, and the annual cover factor. Annual classes follow the breaks 0–5, 5–15, 15–30, 30–50, 50–100, and greater than 100 t ha⁻¹ yr⁻¹.')
    heading(doc, '5.4 Sample and stacking ensemble', 2)
    body(doc, 'The machine-learning target is annual RUSLE soil loss on the aligned annual layer. Valid pixels for sampling numbered 4,527,896. A pixel was kept when the predictors and the soil-loss value were finite and soil loss was at least zero. The design is a class-stratified sample of 12,697 points, random seed 42 (Table 3). The source annual table stored no coordinates, so this is a new draw of that design. Each point stores easting, northing, row, column, and a 2 km spatial-block identifier. The split is 8,888 training points and 3,809 holdout points, stratified by erosion class. The holdout is a random stratified split. Spatial blocking is used only inside training.')
    add_table(doc, 'Table 3. Class-stratified sample drawn from the annual RUSLE soil-loss surface.', ['Class', 'Soil loss (t ha⁻¹ yr⁻¹)', 'Pixels', 'Percent', 'Samples'], [['E1', '0–5', '2,755,730', '60.86', '7,729'], ['E2', '5–15', '1,025,338', '22.64', '2,875'], ['E3', '15–30', '463,379', '10.23', '1,299'], ['E4', '30–50', '162,746', '3.59', '456'], ['E5', '50–100', '88,247', '1.95', '247'], ['E6', '>100', '32,456', '0.72', '91'], ['Total', '—', '4,527,896', '100', '12,697']])
    body(doc, 'Two predictor sets were trained on the same points and the same target. Reduced Integrated uses LS, SOC, C, P, NDVI, and K. Dynamic Integrated uses LS, R, Kₘ, Cₘ, P, RVI, SAVI, and SOC. In the second set, Kₘ, Cₘ, RVI, and SAVI are the annual means of the monthly factors at the point, and Kₘ uses the full-raster percentiles described above. Level-0 models are XGBoost (500 trees, maximum depth 6, learning rate 0.03, subsample 0.8), CatBoost (600 iterations, depth 6, learning rate 0.04, L2 leaf regularisation 3), Random Forest (300 trees, maximum features equal to the square root of the number of predictors, minimum samples to split 4), and a multilayer perceptron with hidden layers of 100 and 50 units, ReLU activations, the Adam solver, L2 penalty 0.001, and early stopping. Perceptron inputs are standardised. Level-1 is a ridge regression with penalty 1.0 and an intercept, fitted only to out-of-fold Level-0 predictions. The folds are five GroupKFold splits on the 2 km blocks inside the training points. The ridge uses only the training folds. Under the sum-of-squares definition used here, R² and the Nash–Sutcliffe efficiency are the same number.')
    heading(doc, '5.5 TreeSHAP', 2)
    body(doc, 'TreeSHAP (Lundberg and Lee, 2017) was applied to the XGBoost member of each stack, on the same 3,809 holdout points. For Reduced Integrated the explanation refers to the member whose holdout R² is 0.451. For Dynamic Integrated it refers to the member whose holdout R² is 0.411. Neither explanation describes the ridge blend or the perceptron. A cover threshold of 0.15 was tested because bare cover is often treated as a distinct management state. No holdout point has annual C below 0.15, and no holdout point has mean monthly Cm below 0.15.')
    heading(doc, '5.6 Calibration of downstream sediment routing', 2)
    body(doc, 'The spatial routing map is the Borselli index passed through the Vigiak sigmoid, SDR = 0.8 / (1 + exp((IC₀ − IC) / 1.2)), with IC₀ = −6.29 and the slope parameter kept at 1.2 (Borselli et al., 2008; Vigiak et al., 2012). On 4,576,196 pixels the mean connectivity is −7.73 and the median is −7.66. The threshold −6.29 is the value that sets the unweighted mean delivery ratio to 0.20, the Vanoni ratio for the 984 km² catchment. The median ratio on that grid is 0.19. Figure 2 is that map. The file is output/rasters/sensitivity/SDR_IC0_vanoni_0.20.tif.')
    body(doc, 'The default European threshold IC₀ = 0.5, with the Vigiak slope parameter kept at 1.2, returns a mean delivery ratio of 0.00105 on this plateau, where the mean connectivity is −7.73. That is a median ratio of 0.00089 and 14,873 t yr⁻¹ on the linear-cover map. The Vanoni ratio of 0.20 is about 190 times that default mean. Recalibrating only the inflection to −6.29 sets the unweighted mean delivery ratio to 0.20, the regional Vanoni baseline, and that calibrated grid is the routing map. On the multiple-flow Copernicus soil-loss surface the same ratio carries 1.35 million m³ yr⁻¹ to the outlet of sub-watershed 2A219, which drains toward the Tilaiya impoundment. The default grid is retained as output/connectivity/SDR.tif so the contrast can be reproduced. Setting the threshold instead to the median connectivity, −7.66, raises the mean ratio to 0.39 and the mass-weighted ratio on the linear-cover map to 0.47, which delivers 2.87 million m³ yr⁻¹. That volume sits above the live-storage loss of 1.01 million m³ yr⁻¹. Thresholds of −5.82, −6.29, and −6.69 give unweighted means of 0.15, 0.20, and 0.25. On the published linear-cover map the threshold −6.29 has a mass-weighted ratio of 0.27 and delivers 1.61 million m³ yr⁻¹. The earlier steepest-descent Copernicus soil-loss grid delivers 1.14 million m³ yr⁻¹ at the same threshold (Section 6.5). The equality of the unweighted mean with 0.20 is the choice of threshold. It is not a sediment gauge at the dam.')
    body(doc, 'On the multiple-flow Copernicus soil-loss grid the same ratio has a mass-weighted value of 0.22 and carries 1.95 million t yr⁻¹, or 1.35 million m³ yr⁻¹ at 1.45 t m⁻³, to the outlet of sub-watershed 2A219. The cells in the highest fifth of the ratio, mean 0.32, are 20 percent of the area and carry 38 percent of that delivered mass. The lowest fifth, mean 0.09, carries 6.5 percent. Among the five rainfall cells, cell 4 is 27 percent of the area, has a mean ratio of 0.22, and carries 45 percent of the delivered mass. Cell 3 is 66 percent of the area, has a mean ratio of 0.20, and carries 47 percent. Because the sigmoid increases with the connectivity index, the new threshold rescales the ratios and leaves the ranking of cells unchanged. The paths end at the outlet of sub-watershed 2A219, and that outlet drains toward the Tilaiya impoundment. The reservoir shoreline lies outside the mask.')
    add_figure(doc, ((FIGURES / 'maps') / 'SDR_IC0_vanoni.png'), 'Figure 2. Sediment delivery ratio with IC₀ = −6.29. The unweighted mean is 0.20. Higher values are the paths the connectivity index ranks as more likely to reach the outlet of sub-watershed 2A219. The colour stretch is the 2nd to 98th percentile. The frame is WGS 84 / UTM zone 45N.')
    heading(doc, '6. Spatiotemporal scenario dynamics and model diagnostics', 1)
    body(doc, 'The results move from the rainfall year to the rate that can be used for planning. Two terrain grids are reported because they answer different questions. The legacy slope-length grid, set by whole-metre ALOS elevations, is retained for the twelve-month series. Holding that grid fixed makes month-to-month differences a record of erosivity and cover. On that grid the factor is exactly zero on 44.36 percent of the annual-support pixels, the mean is 136 t ha⁻¹ yr⁻¹, and the median is 21.7. The unfilled Copernicus GLO-30 multiple-flow grid is the annual terrain result. It reduces that zero class to 1.0 percent. Its soil-loss median of 72 t ha⁻¹ yr⁻¹ lies in the 51–75 band implied by the Central Water Commission live-storage loss at a Vanoni delivery ratio of 0.20, and its mean of 140 t ha⁻¹ yr⁻¹ stays outside that band. Sections 6.1 and 6.2 describe the linear-cover Arnoldus scenario on the legacy grid. Section 6.3 places the published mean beside regional rates and separates the five RUSLE factors. Section 6.4 replaces cover, erosivity, and support practice, and reads each mean against the live-storage yield, the calibrated delivery map (Figure 2), and the area curves. Section 6.5 gives the unfilled multiple-flow grid as the terrain result and keeps the four-satellite fill as a comparison. Section 6.6 compares the perceptron with the tree members on the extreme class of the same RUSLE surface. No scenario is adopted as a calibrated erosion rate for the reservoir.')
    heading(doc, '6.1 Rainfall and erosivity in 2025', 2)
    body(doc, 'Annual rainfall on the five watershed cells ranged from 1,090 mm to 1,443 mm, and corrected Arnoldus erosivity on the same cells ranged from 6,854 to 12,083 MJ mm ha⁻¹ h⁻¹ yr⁻¹ (Table 4). The Renard and Freimund (1994) equations, fitted in the United States, give 16,451 to 35,708 on that rainfall. The monthly maps use the Arnoldus values. Rainfall differs across the watershed. Cell 1, in the south-west of the grid, received more rain in June (324 mm) than in July (272 mm), so its erosivity peaks in June, whereas the other four cells peak in July (Table 5). July rainfall on the watershed raster ranged from 272.4 mm to 480.1 mm, with a pixel-weighted mean of 336.1 mm and a pixel-weighted erosivity of 3,689 MJ mm ha⁻¹ h⁻¹ month⁻¹. Because the drier cells cover more of the watershed, this mean lies below the unweighted mean of the five cells. January, February and December are zero on every cell. Both equations use published coefficients. July contains about half of the linear-cover annual mean, so the monthly maps time the erosion pulse. They do not fix the annual magnitude. Corrected Arnoldus erosivity on the five cells runs from 6,854 to 12,083 MJ mm ha⁻¹ h⁻¹ yr⁻¹, and replacing the catchment total with the reanalysis floor of 772 moves the annual soil-loss mean by about a factor of ten. Cover that is in place before July addresses the month that carries half the year’s detachment. The annual size remains the quantity bounded by the factor chosen. Figure 3 shows monthly rainfall and Figure 4 shows July.')
    add_table(doc, 'Table 4. Annual rainfall and published annual erosivity for the five IMD cells that intersect the watershed, 2025. The Arnoldus column is the equation used in the maps.', ['Cell', 'Longitude (°E)', 'Latitude (°N)', 'Rainfall (mm)', 'Arnoldus R', 'Renard and Freimund R'], [['1', '85.25', '24.00', '1,220', '8,133', '20,801'], ['2', '85.50', '24.00', '1,399', '11,610', '33,819'], ['3', '85.25', '24.25', '1,090', '6,854', '16,451'], ['4', '85.50', '24.25', '1,263', '9,504', '25,738'], ['5', '85.25', '24.50', '1,443', '12,083', '35,708']])
    add_table(doc, 'Table 5. Monthly share of the corrected Arnoldus annual total. Erosivity is in MJ mm ha⁻¹ h⁻¹ month⁻¹. The July share is the fraction of the annual total.', ['Cell', 'June Rₘ', 'July Rₘ', 'July share', 'Peak month'], [['1', '3,249', '2,302', '0.28', 'June'], ['2', '1,603', '5,111', '0.44', 'July'], ['3', '1,546', '3,154', '0.46', 'July'], ['4', '1,177', '4,997', '0.53', 'July'], ['5', '1,636', '6,904', '0.57', 'July']])
    add_figure(doc, ((FIGURES / 'maps') / 'Rainfall_monthly_2025.png'), 'Figure 3. Monthly rainfall in 2025. Each colour is constant inside an IMD 0.25° cell. January, February, and December are dry on every watershed cell.')
    add_figure(doc, ((FIGURES / 'maps') / 'Rainfall_July_2025.png'), 'Figure 4. Rainfall in July 2025. On the watershed cells the values range from 272.4 mm to 480.1 mm.')
    heading(doc, '6.2 Intra-annual dynamics: the July peak', 2)
    body(doc, 'Mean monthly RUSLE-estimated soil loss is negligible from November through February, rises through the pre-monsoon, and is concentrated in June, July and August (Table 6). The June, July and August means are 27.7, 65.4 and 21.5 t ha⁻¹. July and August use 4,154,545 pixels, because the interpolated cover needs both June and September. The July median is 9.92 t ha⁻¹ and the July 95th percentile is 261 t ha⁻¹. Mean cover falls from 0.636 in June to 0.584 in July and 0.532 in August. No July or August pixel on these maps sits on the cover floor of 0.001, and no July pixel has cover below 0.15. Mean Kₘ stays between 0.0393 and 0.0398 in every month, because each month is scaled to its own VV percentiles, so January and July share a similar mean Kₘ. Mean VV is −11.1 dB in January and −8.8 dB in July. The literal minimum and maximum of the twelve-month stack are −33.9 and 16.4 dB. No earlier Sentinel-1 year is in the aligned data, so these are the full extremes available here. An inventory of Tilaiya_2020 through Tilaiya_2025 finds 12 of the 72 monthly stacks. Those twelve are the months of 2025. The other 60 are absent, so a 2020–2025 envelope cannot be calculated. On the 2025 extremes, mean Kₘ is 0.0392 in January and 0.0399 in July, and the annual mean on the 4,138,768 pixels of the static-K test is 134 t ha⁻¹ yr⁻¹. The pooled 5th and 95th percentiles of the year are −14.2 and −6.6 dB. With those bounds, mean Kₘ is 0.0387 in January and 0.0416 in July, the July mean is 68.1 t ha⁻¹, and the annual mean is 140 t ha⁻¹ yr⁻¹, with 34 percent of the area above 100. Each pixel’s own annual minimum and maximum gives the same annual mean, 140, with mean Kₘ of 0.0379 in January and 0.0423 in July, and a July mean of 68.4 t ha⁻¹. The coefficient 0.25 still limits any monthly increase to 25 percent of base K. Mean VV moves only from −11.1 dB in January to −8.8 dB in July, while the literal stretch runs from −33.9 to 16.4 dB, so the seasonal shift is a small fraction of the envelope. The 2025 envelope does not create a monsoon pulse in Kₘ. The reported maps keep the within-month stretch. The annual mean, on the same 4,154,545 pixels (90.8 percent of the watershed), is 136 t ha⁻¹ yr⁻¹ and the median is 21.7 t ha⁻¹ yr⁻¹ (Table 8). Forty-eight percent of the annual map falls in the 0–5 t ha⁻¹ yr⁻¹ class and 33 percent exceeds 100 t ha⁻¹ yr⁻¹, the low class being the cells whose LS factor is zero. Figures 5–11 show the factors, Figure 12 the annual classes, and Figure 13 the twelve monthly maps.')
    add_table(doc, 'Table 6. Monthly RUSLE-estimated soil loss in 2025 with corrected Arnoldus erosivity and interpolated July and August cover. Means, medians, and 95th percentiles are in t ha⁻¹. Mean Rₘ is in MJ mm ha⁻¹ h⁻¹ month⁻¹.', ['Month', 'Mean Aₘ', 'Median', '95th percentile', 'Mean Cₘ', 'Mean Rₘ'], [['January', '0', '0', '0', '0.685', '0'], ['February', '0', '0', '0', '0.700', '0'], ['March', '0.600', '0.072', '2.51', '0.735', '24.2'], ['April', '1.10', '0.062', '4.52', '0.719', '53.7'], ['May', '3.33', '0.455', '13.7', '0.628', '170'], ['June', '27.7', '4.59', '107', '0.636', '1,515'], ['July', '65.4', '9.92', '261', '0.584', '3,689'], ['August', '21.5', '2.90', '88.4', '0.532', '1,293'], ['September', '8.97', '1.11', '36.6', '0.480', '581'], ['October', '7.10', '1.12', '27.5', '0.533', '444'], ['November', '0.207', '0.029', '0.816', '0.641', '10.7'], ['December', '0', '0', '0', '0.685', '0']])
    body(doc, 'On the 4,154,545 pixels with a valid June and a valid interpolated July, 48 percent are below 0.01 t ha⁻¹ in both months. The June median is 4.65 t ha⁻¹ and the July median is 9.92 t ha⁻¹, so July is higher because erosivity is higher and cover stays on the optical scale. Forty-four percent of these pixels have an LS factor of exactly zero, which is the combined slope-length and steepness factor, and soil loss on those cells is zero in every month. That group accounts for the values below 0.01. Interpolated July cover is above 0.15 everywhere in this set (Table 7). Ninety-six percent of the pixels have July cover above 0.40, and their median soil loss is 7.90 t ha⁻¹ in July and 3.76 t ha⁻¹ in June, with a median LS factor of 0.35, just above the large group of zero-LS cells.')
    add_table(doc, 'Table 7. June and July soil loss on the 4,154,545 pixels with interpolated July cover. Soil loss is in t ha⁻¹. The LS column is the combined slope-length and steepness factor. No pixel in this set has July cover below 0.15.', ['July cover', 'Share', 'Share of the class below 0.01', 'Median July', 'Median June', 'Median LS factor'], [['0.15 to 0.40', '4.3%', '32%', '43.5', '17.0', '1.52'], ['above 0.40', '95.7%', '49%', '7.90', '3.76', '0.35']])
    body(doc, 'The principal annual figure uses the corrected Arnoldus erosivity, with the July and August cover interpolated from June and September. On the 4,154,545 pixels that are valid in all twelve months, the mean is 136 t ha⁻¹ yr⁻¹ and the median is 21.7 t ha⁻¹ yr⁻¹. The primary RUSLE scenario gives a gross soil-loss mass of 8.82 million t yr⁻¹, equivalent to approximately 6.08 million m³ yr⁻¹ when converted using the assumed bulk density of 1.45 t m⁻³. Radar cover on the same erosivity gives 87.2 t ha⁻¹ yr⁻¹, equivalent to 3.90 million m³ yr⁻¹ at that same density. The Renard and Freimund annual total, applied to the interpolated cover with the same monthly shares of rainfall, gives 346 t ha⁻¹ yr⁻¹, equivalent to 15.5 million m³ yr⁻¹ (Table 8).')
    add_table(doc, 'Table 8. Annual soil loss on the 4,154,545 pixels valid in all twelve months. The volume column is soil-loss mass divided by the assumed bulk density of 1.45 t m⁻³. The Arnoldus rows use the monthly maps. The Renard and Freimund row uses the same monthly rainfall shares and the interpolated cover.', ['Case', 'Mean (t ha⁻¹ yr⁻¹)', 'Median', 'Gross volume (million m³ yr⁻¹)'], [['Interpolated optical, Arnoldus', '136', '21.7', '6.08'], ['Radar cover, Arnoldus', '87.2', '12.8', '3.90'], ['Interpolated optical, Renard and Freimund', '346', '53.4', '15.5']])
    add_figure(doc, ((FIGURES / 'maps') / 'LS_2025.png'), 'Figure 5. Slope-length and steepness factor. LS is the combined factor. Cells with no slope on the whole-metre elevation grid are exactly zero.')
    add_figure(doc, ((FIGURES / 'maps') / 'C_annual_baseline_2025.png'), 'Figure 6. Annual cover-management factor from the aligned baseline. The minimum on this layer is 0.284, so no pixel is below 0.15.')
    add_figure(doc, ((FIGURES / 'maps') / 'P_2025.png'), 'Figure 7. Support-practice factor. This layer is static through the year.')
    add_figure(doc, ((FIGURES / 'maps') / 'Cm_monthly_2025.png'), 'Figure 8. Monthly cover factor stored with the satellite stacks. January–June and September–December use SAVI. July and August use the radar index. The reported soil-loss maps replace those two months with cover interpolated from June and September.')
    add_figure(doc, ((FIGURES / 'maps') / 'Km_monthly_2025.png'), 'Figure 9. Monthly erodibility factor used inside the reported RUSLE product. Each month is stretched to its own Sentinel-1 VV percentiles, so the months share a similar Km range. The stretch is a within-month heuristic.')
    add_figure(doc, ((FIGURES / 'maps') / 'Cm_July_2025.png'), 'Figure 10. July cover from the stored radar index. This is the sensitivity layer. The reported July soil-loss map uses cover interpolated from June and September.')
    add_figure(doc, ((FIGURES / 'maps') / 'Km_July_2025.png'), 'Figure 11. July soil erodibility after the within-month stretch of Sentinel-1 VV backscatter. The colour scale is the 2nd to 98th percentile of this month, so spatial differences can be seen. The catchment mean remains near 0.04 t ha h ha⁻¹ MJ⁻¹ mm⁻¹. Incidence angle and terrain are still present in the backscatter.')
    add_figure(doc, ((FIGURES / 'maps') / 'SoilLoss_Arnoldus_annual_class_2025.png'), 'Figure 12. Annual soil loss for 2025 under corrected Arnoldus erosivity and linear cover, with July and August cover interpolated from June and September. Only pixels valid in all twelve months are classified. Classes are 0–5, 5–15, 15–30, 30–50, 50–100, and greater than 100 t ha⁻¹ yr⁻¹. The extensive green class is the cells whose slope-length factor is zero. Grey inside the boundary is NoData. Coordinates are WGS 84 / UTM zone 45N.')
    add_figure(doc, ((FIGURES / 'maps') / 'SoilLoss_Arnoldus_monthly_2025.png'), 'Figure 13. Monthly soil loss for 2025 under the same Arnoldus scenario as Figure 12. All panels share a scale from 0 to 50 t ha⁻¹ month⁻¹, and values above 50 are shown in the darkest red, so the monsoon months can be compared with the dry season. January, February, and December are near zero. July is the peak month.')
    body(doc, 'The annual total is strongly skewed (Figure 14). On a logarithmic axis the lower half of the map remains near the floor, the reported median is 21.7 t ha⁻¹ yr⁻¹, and the mean of 136 t ha⁻¹ yr⁻¹ is carried by the upper tail. A linear plot of the same values hides that separation.')
    add_figure(doc, ((FIGURES / 'maps') / 'SoilLoss_annual_log_distribution.png'), 'Figure 14. Cumulative distribution of annual soil loss for the linear-cover Arnoldus scenario. The vertical axis is logarithmic. Values below 0.1 t ha⁻¹ yr⁻¹ are drawn at 0.1 so the low class remains visible. The dashed line is the reported median, 21.7 t ha⁻¹ yr⁻¹, and the dotted line is the reported mean, 136 t ha⁻¹ yr⁻¹.')
    body(doc, 'A stacking model was fitted to the annual RUSLE surface. On a random stratified holdout its R² is 0.832. The target is that RUSLE surface and the predictors include its factors, so the score measures recovery of the reference estimate. Section 6.6 gives the member comparison. The full tables remain in the supplement. The fit was not used to change the 2025 maps.')
    heading(doc, '6.3 Comparison with published rates', 2)
    body(doc, 'Table 9 sets the 2025 maps beside published rates for this region and for RUSLE studies more generally. Each row estimates a different quantity. Ghosh et al. (2025) and Biswas and Pani (2015) report annual gross soil loss for the Damodar and the Barakar, Borrelli et al. (2021) report medians across many modelled studies, Central Water Commission (2021) reports a reservoir volume. Sardar et al. (2014) is cited as a SWAT study. The printed unit awaits verification from the typeset PDF, so Table 9 uses the Central Water Commission volume. Pandey et al. (2007) report how close a USLE sediment yield came to measurements at Karso. The rows for this study are hillslope soil-loss scenarios on the 715 km² mask for one year.')
    add_table(doc, 'Table 9. Published rates set beside the 2025 results. Soil loss is in t ha⁻¹ yr⁻¹. Volumes are annual. Each row has its own boundary, year, and measurement.', ['Source', 'What was estimated', 'Value'], [['Present study', 'RUSLE-estimated mean annual soil loss, 715 km², 2025', '136 (median 21.7)'], ['Present study', 'Area above 100 t ha⁻¹ yr⁻¹', '33 percent'], ['Present study', 'July mean, from Table 6', '65.4'], ['Present study', 'Soil-loss mass and equivalent volume at 1.45 t m⁻³', '8.82 million t; 6.08 million m³'], ['Ghosh et al. (2025)', 'Damodar basin, annual RUSLE mean', '12.86 in 2017; 12.06 in 2024'], ['Biswas and Pani (2015)', 'Barakar basin, area above 100', '0.08 percent'], ['Borrelli et al. (2021)', 'Median gross rate, many studies', '9.6 USLE; 12.6 RUSLE'], ['Central Water Commission (2021)', 'Live-storage loss, and the same loss per hectare of 98,420 ha', '1.01 million m³ yr⁻¹; 10.3–14.9 t ha⁻¹ yr⁻¹'], ['Pandey et al. (2007)', 'Karso, USLE yield against measurements', 'Deviation 1.37–13.85 percent']])
    body(doc, 'The linear-cover Arnoldus scenario has a mean of 136 t ha⁻¹ yr⁻¹ and a median of 21.7. The median is produced by an LS factor of exactly zero on 44 percent of the shared pixels. A standard slope-length equation moves that median to 64 and 62. The Damodar means are 12.06 and 12.86 t ha⁻¹ yr⁻¹ (Ghosh et al., 2025), and the global RUSLE median compiled by Borrelli et al. (2021) is 12.6. The median of 21.7 is a different statistic from those means. The mean of 136 is about ten times the Damodar means, and 33 percent of the map exceeds 100 t ha⁻¹ yr⁻¹, against 0.08 percent of the Barakar (Biswas and Pani, 2015). Those published means use different erosivity equations. Ghosh et al. (2025) convert annual rainfall with R = 0.363 P + 79, which gives 514–983 MJ mm ha⁻¹ h⁻¹ yr⁻¹ in 2017 and 507–814 in 2024. Biswas and Pani (2015) use the Renard and Freimund (1994) monthly form, the average of three power terms in r²/P, and sum the months. Chen et al. (2023) found 125 papers that copied the Arnoldus equation with the wrong coefficients, many of them from India. A soil-loss mean near 12 t ha⁻¹ yr⁻¹ therefore records the erosivity equation that study used.')
    body(doc, 'Table 10 separates the five factors on the 4,154,545 annual pixels. Mean R is 7,783 MJ mm ha⁻¹ h⁻¹ yr⁻¹. The Raj et al. (2022) India erosivity grid, the IMDAA hourly product for 1979–2018 at 0.12°, averages 772 on the same pixels, with cell values from 605 to 1,021. A cell near Cherrapunji on that grid is 10,206, so the file reaches high values. The mask sample sits with the Hazaribagh district average in the same workbook, 690, and below the Jharkhand state average of 1,198 (range 362–3,869). Jharkhand is the relevant comparison. Das et al. (2025) note that satellite and reanalysis erosivity is significantly underestimated in the tropics, and this grid is an IMDAA reanalysis product, so 772 is a floor with a known low bias. Their monthly maps, from 261 hourly and 2,525 monthly stations, are the direct test of the allocation Pm²/ΣPm². The maps are available from the corresponding author on request and were not obtained. On their station comparison, the unit-converted Arnoldus equation has a mean error of about −9 percent, with station errors from about −75 percent to +75 percent. That station error does not make 7,783 and 772 co-equal bounds. Tiwari et al. (2015) was not sampled. Mean base K is 0.035. Mean LS is 1.38 and the median is 0.40, so slope length is not an order-of-magnitude outlier. The erosivity-weighted linear cover is 0.579. The same weight on the exponential NDVI cover is 0.167, a ratio of 3.56. Mean P is 0.68, which lowers the product relative to a practice factor of 1.')
    add_table(doc, 'Table 10. Factor budget on the 4,154,545 annual pixels. R is in MJ mm ha⁻¹ h⁻¹ yr⁻¹. The comparison for R is the Raj et al. (2022) reanalysis floor. The comparison for C is the erosivity-weighted exponential of NDVI. The comparison for P is 1.', ['Factor', 'Reported mean', 'Comparison mean', 'Ratio'], [['R', '7,783', '772', '10.1'], ['K', '0.035', '—', '—'], ['LS', '1.38', '—', '—'], ['C', '0.579', '0.167', '3.56'], ['P', '0.68', '1', '0.68']])
    body(doc, 'The twelve monthly means in Table 6 add to 136 t ha⁻¹. June, July and August contribute 27.7, 65.4 and 21.5, together 115 t ha⁻¹, and July alone is almost half of the annual mean, a seasonal concentration that the annual Damodar and Barakar maps leave inside one annual total. One rainfall cell peaks in June and the other four peak in July. Pandey et al. (2007) remain the nearby study in which a USLE yield was compared with measurements, with a deviation of 1.37 to 13.85 percent at Karso, and no equivalent check was made here.')
    body(doc, 'The linear-cover mass is 8.82 million t yr⁻¹, or 6.08 million m³ yr⁻¹ at 1.45 t m⁻³ (Table 8). The Commission live-storage loss of 1.01 million m³ yr⁻¹ is 10.3 t ha⁻¹ yr⁻¹ at 1.0 t m⁻³ and 14.9 t ha⁻¹ yr⁻¹ at 1.45 t m⁻³ over 98,420 ha. That loss records live capacity only, so it is a lower bound on the sediment volume retained in the reservoir. The mask is 715 km² and the reservoir figure refers to 984 km². A hillslope mean of 136 would need a delivery ratio near 0.11 to match 14.9. The ratio 1.01 / 6.08 = 0.17 assigns the whole-dam loss to this mask alone. Gross hillslope loss is expected to exceed reservoir deposition. The routing map is the connectivity grid at IC₀ = −6.29 (Section 5.6 and Figure 2). Its unweighted mean ratio is 0.20. The default threshold of 0.5 gives a mean of 0.00105 and 14,873 t yr⁻¹. Recentering on the median connectivity raises the mean to 0.39 and delivers 2.87 million m³ yr⁻¹, above the live-storage loss. The area curves remain the lumped check on that map.')
    heading(doc, '6.4 Reconciling hillslope scenarios with reservoir siltation', 2)
    body(doc, 'The Central Water Commission live-storage survey supplies the 68-year benchmark that reconciles the hillslope scenarios with reservoir sedimentation. Live capacity fell from 199.89 million m³ to 131.235 million m³, a loss of 68.655 million m³, about 1.01 million m³ yr⁻¹. Over the 98,420 ha official catchment that is a net delivery of 10.3 t ha⁻¹ yr⁻¹ at 1.0 t m⁻³ and 14.9 t ha⁻¹ yr⁻¹ at 1.45 t m⁻³. Coupled with the Vanoni delivery ratio of 0.20, the gross detachment consistent with that loss is 51–75 t ha⁻¹ yr⁻¹. That band sits between the scenario extremes. Linear cover, 136 t ha⁻¹ yr⁻¹, is the upper bound, where the SAVI coefficient leaves more of the bare-soil rate than the published cover factors. The European exponential of NDVI, 27.6 t ha⁻¹ yr⁻¹, is the lower bound. Its coefficient was set for Europe and was not fitted here. No calculated mean falls inside 51–75. The Copernicus multiple-flow median of 72 does. The band is the planning target. Every row calculated before this step kept the linear cover, and none of them lowered R below the Arnoldus total. The span 87–346 t ha⁻¹ yr⁻¹ is the high side of that family. Cover and erosivity were then replaced one at a time on the same 4,154,545 pixels, leaving LS, Kₘ, and P unchanged. Soil loss in each month was multiplied by the ratio of the new cover to the linear cover, or by the ratio of the India-grid R to the Arnoldus R at that pixel.')
    body(doc, 'The exponential of NDVI lowers July cover from 0.584 to 0.167, and the share of July pixels above 0.40 falls from 96 percent to 7.2 percent. The coefficient in that exponential was set for Europe (van der Knijff et al., 2000) and is uncalibrated at Tilaiya, and the July and August index is interpolated before the exponential is applied. October NDVI has a median of 0.67. The exponential of that NDVI has a median of 0.018, while the annual baseline cover beside it in Table 16 has a median of 0.70. The annual mean falls from 136 to 27.6 t ha⁻¹ yr⁻¹, the median from 21.7 to 1.11, and the area above 100 t ha⁻¹ yr⁻¹ from 33 percent to 5.8 percent.')
    body(doc, 'The ratio of erosivity-weighted cover is 3.56 (Table 10). The ratio of the two soil-loss means is 136 / 27.6 = 4.92. Weighting that cover ratio by R × LS raises it from 3.56 to 4.70. Adding K and P raises it to 4.77. Most of the step from 3.56 to about 5 is spatial covariance with LS. The remaining step, from 4.77 to 4.92, comes from the monthly product.')
    body(doc, 'A third cover uses the land-cover attribute table as C: built-up 0.002, cropland 0.28, vegetation 0.005, water 0, and barren land 1, assigned by the nearest class code. On the same 4,154,545 pixels the mean is 28.8 t ha⁻¹ yr⁻¹, the median is 0.31, and 6.3 percent of the area exceeds 100. Mean linear cover on vegetation is 0.51, against a table value of 0.005. Mean linear cover on built-up is 0.71, against a table value of 0.002. The scenario mean still lands near the exponential-cover result, because barren land keeps C = 1 and cropland keeps 0.28. The geography of the three cover scenarios is not the same (Table 12). Under linear cover, vegetation is 40 percent of the area and 60 percent of the soil-loss mass, and barren land is 2.2 percent of the area and 3.2 percent of the mass. Under the exponential cover, barren land rises to 8.2 percent of the mass. Under the lookup, barren land carries 23 percent of the mass and vegetation falls to 2.9 percent, because one cover value of 0.005 is applied to the whole vegetation class and one value of 1 is applied to the whole barren class.')
    body(doc, 'Table 11 sets the erosivity-weighted class means of the linear and exponential covers beside published values. Jain and Kothyari (2000) assign handbook cover factors at Karso, the gauged watershed beside Tilaiya: fairly dense forest 0.003, open scrub 0.040, and agriculture, mainly paddy, 0.260. The same paper assigns Nagwa wasteland a cover of 0.400. Biswas and Pani (2015) assign the Barakar classes from earlier studies after a field check of the land-cover map: built-up 1, agriculture 0.28, wasteland 0.18, vegetation 0.06, and water 0. Those Jharkhand numbers are class assignments. The runoff-plot measurements are from CSWCRTI at Dehradun (Narain et al., 2001): Chrysopogon fulvus 0.04, conventional maize 0.41, and maize given 4 t ha⁻¹ of mulch 0.10. The Dehradun plots lie outside the Chota Nagpur plateau. No Chota Nagpur plot table was obtained.')
    add_table(doc, 'Table 11. Erosivity-weighted cover by nearest land-cover class on the annual support. Linear and exponential values are the cover factors in the 2025 scenarios. Lookup values are the attribute table. The last column quotes the published numbers named above.', ['Class', 'Linear C', 'Exponential C', 'Lookup C', 'Published cover'], [['Built-up', '0.71', '0.36', '0.002', 'Barakar built-up 1'], ['Cropland', '0.61', '0.20', '0.28', 'Karso paddy 0.26; Barakar crop 0.28; Dehradun maize 0.41'], ['Vegetation', '0.51', '0.071', '0.005', 'Karso forest 0.003 and scrub 0.04; Barakar vegetation 0.06; Dehradun grass 0.04'], ['Water', '0.71', '0.39', '0', 'Barakar water 0'], ['Barren land', '0.66', '0.33', '1', 'Nagwa wasteland 0.40; Barakar wasteland 0.18']])
    body(doc, 'The linear means on the two large classes, 0.61 on cropland and 0.51 on vegetation, sit above the crop, scrub, grass, and forest values. The exponential means are 0.20 on cropland and 0.071 on vegetation. The crop value lies just below the Karso paddy assignment and the Barakar crop assignment, and below the Dehradun maize plot. The vegetation value lies close to the Barakar vegetation assignment and above the scrub and grass values, and it remains well above dense forest. This vegetation class mixes forest, plantation, scrub, and fallow, so one mean cannot stand for 0.003 and 0.04 together. The lookup matches the crop assignments and the dense-forest assignment. It still gives 0.005 to that mixed vegetation class and 1 to barren land. Exponential cover on barren land is 0.33, between the wasteland assignments of 0.40 and 0.18, while the linear mean there is 0.66. Built-up has no plot value in these sources. The lookup uses 0.002 and the Barakar assignment uses 1. Satellite means on the water class stay high because nearest-class rounding of the bilinear land-cover grid mixes land into that class. July means by class stay within 0.02 of the annual values in Table 11. The coefficient 2 remains the European calibration. This comparison leaves the mapped linear cover in place, and the reported mean stays 136 t ha⁻¹ yr⁻¹.')
    add_table(doc, 'Table 12. Share of annual soil-loss mass by nearest land-cover class, on the 4,154,545 annual pixels. Area is the class share of those pixels. Each mass column is the class total divided by the scenario total.', ['Class', 'Area', 'Linear cover', 'Exponential cover', 'Lookup cover'], [['Built-up', '4.4 percent', '0.3 percent', '0.6 percent', '0.0 percent'], ['Cropland', '51 percent', '34 percent', '52 percent', '75 percent'], ['Vegetation', '40 percent', '60 percent', '34 percent', '2.9 percent'], ['Water', '2.4 percent', '2.3 percent', '5.2 percent', '0'], ['Barren land', '2.2 percent', '3.2 percent', '8.2 percent', '23 percent']])
    body(doc, 'Setting P to 1 wherever the current practice factor is positive raises the linear-cover mean from 136 to 182 t ha⁻¹ yr⁻¹. The median rises from 21.7 to 34.3, and the area above 100 rises from 33 percent to 40 percent. Pixels with P = 0 stay at zero soil loss, so built-up and water remain excluded. The change is the removal of P = 0.5. Cropland, 51 percent of the area, carries 34 percent of the linear-cover mass and 49 percent of the mass once P is 1. Its class mean rises from 90 to 174 t ha⁻¹ yr⁻¹. The factor 0.5 on cropland is an unevidenced reduction: the grid applies it, and no practice survey is attached to it.')
    body(doc, 'Substituting the Raj et al. (2022) magnitude for the 2025 Arnoldus total, and keeping the linear cover, lowers the mean from 136 to 12.9 t ha⁻¹ yr⁻¹ and the area above 100 from 33 percent to 1.4 percent. That substitution places a 1979–2018 reanalysis magnitude on the 2025 rainfall pattern. It uses the low-biased floor from Section 6.3, not a second estimate of equal standing. Applying the exponential cover and that floor together gives a mean of 2.88 t ha⁻¹ yr⁻¹. Chen et al. (2023) still defend the factor 17.02 and the intercept −0.8188, so the Arnoldus equation was not rewritten. The reported monthly rasters were left in place.')
    add_table(doc, 'Table 13. Cover and erosivity replacements on the 4,154,545 annual pixels. Means and medians are in t ha⁻¹ yr⁻¹. Gross volume is soil-loss mass divided by 1.45 t m⁻³, in million m³ yr⁻¹.', ['Case', 'Mean', 'Median', 'Area above 100', 'Gross volume'], [['Linear cover, Arnoldus R', '136', '21.7', '33 percent', '6.08'], ['Linear cover, P = 1', '182', '34.3', '40 percent', '8.15'], ['Exponential NDVI cover, Arnoldus R', '27.6', '1.11', '5.8 percent', '1.24'], ['Land-cover lookup, Arnoldus R', '28.8', '0.31', '6.3 percent', '1.29'], ['Linear cover, India-grid R', '12.9', '2.20', '1.4 percent', '0.58'], ['Exponential NDVI cover, India-grid R', '2.88', '0.086', '0.14 percent', '0.13']])
    body(doc, 'The reservoir figure is a sediment yield, so a hillslope mean has to exceed it. Live-storage loss of 1.01 million m³ yr⁻¹ is 10.3 t ha⁻¹ yr⁻¹ at 1.0 t m⁻³ and 14.9 t ha⁻¹ yr⁻¹ at 1.45 t m⁻³ over 98,420 ha. That loss records live capacity only, so the specific rate is a lower bound on sediment retained in the reservoir. The yield is an average over 984 km². The scenario means are averages over the 715 km² mask. The comparison uses the mask mean as the rate for this headwater and does not scale the mask up to 984 km². Lim et al. (2005) state three area curves, with area in km²:', first_line=False)
    equation(doc, 'SDR = 0.4724 × A^(−0.125)    (Vanoni, 1975)')
    equation(doc, 'SDR = 0.5656 × A^(−0.11)    (USDA, 1972)')
    equation(doc, 'SDR = 0.3750 × A^(−0.2382)    (Boyce, 1975)')
    body(doc, 'None of the three curves was fitted at Tilaiya. On the official 984 km² catchment the Vanoni ratio is 0.20, so the hillslope rate that would supply the live-storage loss is 51–75 t ha⁻¹ yr⁻¹. The USDA curve gives 0.27 and 39–56 t ha⁻¹ yr⁻¹. The Boyce curve gives 0.073 and 141–205 t ha⁻¹ yr⁻¹. Table 14 tests every Table 13 row against the yield and against the Vanoni band. Because the yield itself is a lower bound, that band is a lower-bound window on the gross rate.')
    add_table(doc, 'Table 14. Each Table 13 mean against the live-storage yield and the Vanoni window. Implied SDR is the yield of 10.3–14.9 t ha⁻¹ yr⁻¹ divided by the scenario mean. The Vanoni window on the official catchment is 51–75 t ha⁻¹ yr⁻¹.', ['Case', 'Mean', 'Implied SDR', 'Position'], [['Linear cover, Arnoldus R', '136', '0.076–0.11', 'Above 51–75; below Boyce 141'], ['Linear cover, P = 1', '182', '0.056–0.082', 'Above 51–75; inside Boyce 141–205'], ['Exponential NDVI cover, Arnoldus R', '27.6', '0.37–0.54', 'Below 51–75; above the yield'], ['Land-cover lookup, Arnoldus R', '28.8', '0.36–0.52', 'Below 51–75; above the yield'], ['Linear cover, India-grid R', '12.9', '0.79–1.15', 'Below 51–75; short of 14.9'], ['Exponential NDVI cover, India-grid R', '2.88', '3.6–5.2', 'Below both yield bounds']])
    body(doc, 'The linear-cover Arnoldus mean of 136 implies a delivery ratio of 0.076–0.11. It can supply the recorded live-storage loss, and it sits above the Vanoni band and just below the Boyce interval of 141–205. Setting P to 1 raises that mean to 182, which falls inside the Boyce interval and remains above the Vanoni band. The exponential-cover mean of 27.6 and the lookup-cover mean of 28.8 also exceed both yield bounds. They would require a delivery ratio of about 0.4–0.5. The linear-cover India-grid mean of 12.9 exceeds 10.3 and falls short of 14.9, which is a delivery ratio of 0.79–1.15. A ratio near 1 would carry almost all hillslope detachment to the reservoir. The both-replacements mean of 2.88 lies below both yield bounds. The ratio required to supply the deposit would be 3.6–5.2, above 1, so that case cannot be the gross erosion that supplied the live-storage loss.')
    body(doc, 'The fivefold cover spread has three jobs. Linear cover, 136 t ha⁻¹ yr⁻¹, is the uncalibrated upper bound. The SAVI equation uses the adopted coefficient 1.18. Erosivity-weighted cover is 0.61 on cropland and 0.51 on vegetation, above the Karso, Barakar, and Dehradun factors in Table 11, so the equation assigns more of the bare-soil rate than those factors do. Exponential cover, 27.6 t ha⁻¹ yr⁻¹, is the lower bound. The coefficient 2 was set for Europe (van der Knijff et al., 2000) and was not fitted on this catchment, so the curve places the catchment mean below the planning band. On cropland and vegetation the exponential means, 0.20 and 0.071, lie nearer the published factors than the linear means. The lookup mean of 28.8 sits with that lower bound. The band of 51–75 t ha⁻¹ yr⁻¹ is the hydrologically grounded planning target: the gross hillslope rate that supplies the live-storage loss of 1.01 million m³ yr⁻¹ at the Vanoni ratio of 0.20. It reconciles hillslope detachment with the recorded siltation. No calculated RUSLE mean falls inside that band, and no flat 51–75 surface was mapped. The multiple-flow Copernicus median of 72 falls inside the target, and the mean on that grid remains 140 because 41 percent of the area exceeds 100. The yield is a lower bound, because the survey omits dead storage. The Boyce curve remains the wider upper test and places the matching gross rate at 141–205, which contains the practice-factor mean of 182. Values below about 15 t ha⁻¹ yr⁻¹ cannot supply the live-storage yield at 1.45 t m⁻³, and the India-grid rows fall at or below that yield. Among the means that can supply it, Table 12 separates the geography. Linear cover places 60 percent of the mass on vegetation and 3.2 percent on barren land. The lookup places 23 percent of the mass on 2.2 percent barren land and 2.9 percent on 40 percent vegetation, which follows from giving every vegetation pixel a cover of 0.005. The exponential cover is between those patterns. A conservation agency can time works to July from the monthly maps, treat 136 as the upper bound and 27.6 as the lower bound, and use 51–75 as the planning target. The mapped erosivity remains the Arnoldus mean of 7,783 MJ mm ha⁻¹ h⁻¹ yr⁻¹, and 772 is the low-biased reanalysis floor.')
    body(doc, 'Figure 15 places the gross soil-loss map beside the calibrated delivery ratio. Steep cells can detach a large mass and still carry a modest delivery ratio, so the contribution toward the outlet is the product of the two grids, not the gross map alone.')
    add_figure(doc, ((FIGURES / 'maps') / 'SoilLoss_and_SDR_panel.png'), 'Figure 15. Gross annual soil loss (left; classes as in Figure 12) and the calibrated sediment delivery ratio at IC₀ = −6.29 (right). High hillslope detachment is not the same as a large contribution at the outlet. Delivery paths end at the outlet of sub-watershed 2A219.')
    heading(doc, '6.5 Topographic control and the scenario envelope', 2)
    body(doc, 'The primary terrain result is the unfilled Copernicus GLO-30 grid with slope-proportional multiple flow and the Desmet and Govers factor. On the 4,154,545 annual pixels, 1.0 percent have LS exactly zero, the 0–5 class is 11 percent, and the class above 100 is 41 percent. The soil-loss median is 72 t ha⁻¹ yr⁻¹ and the mean is 140 t ha⁻¹ yr⁻¹. The median lies in the 51–75 planning band. The mean of 140 does not. That band remains the gross rate implied by the Central Water Commission live-storage loss of 1.01 million m³ yr⁻¹ at a Vanoni delivery ratio of 0.20. No calculated mean falls inside 51–75, and no flat 51–75 surface was mapped. The grids are output/rasters/sensitivity/LS_copernicus_mfd_desmet.tif and SoilLoss_annual_copernicus_mfd.tif.')
    body(doc, 'Whole-metre storage on the legacy grid forces the slope-length factor to zero on 44.36 percent of the annual-support pixels and holds the soil-loss median at 21.7 t ha⁻¹ yr⁻¹, against a mean of 136. Continuous Copernicus elevations, routed by multiple flow and the Desmet and Govers factor, bring that zero share to 1.0 percent and the median to 72 t ha⁻¹ yr⁻¹. The mean stays at 140 because 41 percent of the area remains above 100, so the steep cells stay in the map while the zero class shrinks to the 1.0 percent of cells that are truly level. The legacy ALOS grid is kept for those twelve months so the series records erosivity and cover. The Copernicus grid is the annual terrain result, and its median lies in the live-storage planning band while the mean of 140 does not.')
    body(doc, 'Table 15 collects the annual scenarios. The mean of 136 t ha⁻¹ yr⁻¹ is the linear-cover Arnoldus case: the published LS raster, heuristic Km, and interpolated July and August cover. On the 4,138,768 pixels where base K and Km are both finite, holding erodibility at base K changes the mean from 136 to 119 and the median from 22.8 to 20.4. The class above 100 remains 31 percent. Heuristic Km rescales this scenario by about 14 percent.')
    body(doc, 'A standard length equation, scored against the legacy grid on the integer-metre DEM, locates the same plateau zeros. Upslope length is the D8 accumulation count times 12.5 m (O’Callaghan and Mark, 1984). The length exponent is 0.2, 0.3, 0.4, or 0.5 as slope crosses 1, 3, and 5 percent (Wischmeier and Smith, 1978). Steepness follows McCool et al. (1989, 1987): 10.8 sin β + 0.03 below 9 percent slope, and 16.8 sin β − 0.50 at 9 percent and above. The equation is then multiplied by 1.124, the median ratio of published LS to the equation where both are positive. Pearson correlation with the published LS is 0.771. On the integer-metre DEM the equation leaves 38 percent of cells at LS exactly zero, against 44.36 percent in the legacy raster, because those exact zeros are equal-metre plateaus. The ALOS tiles available for this catchment are also stored in whole metres.')
    body(doc, 'Copernicus GLO-30 was bilinearly placed on the same 12.5 m grid. Under the same equation, 1.2 percent of cells have LS exactly zero. The annual mean is 103 t ha⁻¹ yr⁻¹ on the integer-metre DEM and 119 on Copernicus, with medians of 64 and 62. Equivalent volumes at 1.45 t m⁻³ are 4.60 and 5.30 million m³ yr⁻¹. July remains the peak month. On Copernicus the July mean is 57.1 t ha⁻¹ and the July median is 29.2, against 23.7 and 13.2 in June. The 0–5 class falls to 7.8 percent, while the class above 100 remains 35 percent. The continuous surface removes most of the exact zeros and leaves a large high class. The published median of 21.7 belongs to the published LS raster. This steepest-descent Copernicus comparison has a median of 62 and a mean of 119. It is an earlier test on the same elevation. The terrain result remains the unfilled multiple-flow grid, median 72 and mean 140. The mean of 119 stays above the 51–75 planning band because 35 percent of the area still exceeds 100. Multiplying this soil-loss grid by the delivery ratio at IC₀ = −6.29 gives a mass-weighted ratio of 0.21 and a delivered volume of 1.14 million m³ yr⁻¹ on 4,138,768 pixels. The live-storage loss is 1.01 million m³ yr⁻¹ over the 984 km² dam catchment. The delivered grid is output/rasters/sensitivity/Delivered_copernicus_LS_IC0_vanoni.tif. The twelve monthly maps hold one slope-length grid, so month-to-month differences are erosivity and cover.')
    body(doc, 'The unfilled multiple-flow grid at the opening of this section is the terrain result. The four-satellite comparison below fills depressions before the same Desmet and Govers equation and is kept as a processing test.')
    body(doc, 'The same multiple-flow equation was applied to four satellite elevations after one conditioning sequence, on the same 4,154,545 annual pixels. ALOS PALSAR is the stored L-band grid in whole metres. Copernicus GLO-30 is the TanDEM-X surface already on the 12.5 m grid. SRTM is the C-band 1-arc-second tile N24E085, bilinearly placed on that grid. ASTER GDEM is Terra optical stereo, not radar. The elevation band of tile ASTGTMV003_N24E085_dem.tif was bilinearly placed on that grid, and the stack-count band was not used. Closed depressions were filled by a priority flood from the watershed boundary. Cells that were still level then rose by 1 mm per cell away from the spill. Cells at the same distance from the spill stay level with one another, and a 1 mm step across 12.5 m is far below 0.5 degrees, so the increment only gives a filled flat a drainage direction. On ALOS, 38.5 percent of cells have no lower neighbour before the fill, and the fill raises no cell: the flat share is still 38.5 percent and the pit share is zero. Those zeros are equal-metre plateaus. After the millimetre step, 13.6 percent remain exactly flat, 38.5 percent are still gentler than 0.5 degrees, the 0–5 class is 43 percent, the median is 94 t ha⁻¹ yr⁻¹, and the mean is 144. Copernicus is flat on 1.0 percent of cells before the fill. The fill raises 4.8 percent of cells and the flat share becomes 5.4 percent, because a filled pit stands level at the spill elevation. After the millimetre step the exact-zero share is 3.3 percent, 14 percent of cells are gentler than 0.5 degrees, the median is 68 t ha⁻¹ yr⁻¹, and the mean is 136. SRTM is flat on 2.5 percent of cells before the fill and on 15.1 percent after it, with 13.3 percent of cells raised. After the millimetre step the exact-zero share is 7.7 percent, 19 percent of cells are gentler than 0.5 degrees, the median is 77 t ha⁻¹ yr⁻¹, and the mean is 136. ASTER is flat on 1.2 percent of cells before the fill and on 23.7 percent after it, with 23.3 percent of cells raised, so the fill increases the flat share. After the millimetre step the exact-zero share is 10.5 percent, 25 percent of cells are gentler than 0.5 degrees, the 0–5 class is 30 percent, the class above 100 is 53 percent, the median is 117 t ha⁻¹ yr⁻¹, and the mean is 220. The median of 117 does not fall in 51–75. The mean of 220 is not the planning rate. The planning target of 51–75 remains the Vanoni gross rate. Copernicus was chosen because it is flat on 1.0 percent of cells before the fill and the fill raises only 4.8 percent. ALOS plateaus stay 38.5 percent flat. The SRTM fill raises the flat share to 15.1 percent. The ASTER fill raises the flat share to 23.7 percent and the mean becomes 220. The filled means of ALOS, Copernicus, and SRTM stay near 136–144. The unfilled Copernicus multiple-flow grid remains the terrain result: a 1.0 percent zero share, a median of 72, and a mean of 140. The mean of 140 lies outside 51–75. No calculated mean falls inside that band. The conditioned grids are output/rasters/sensitivity/LS_alos_filled_mfd.tif, LS_copernicus_filled_mfd.tif, LS_srtm_filled_mfd.tif, and LS_aster_filled_mfd.tif. The twelve monthly maps hold one slope-length grid, so the July peak can be compared from month to month as a change in erosivity and cover.')
    body(doc, 'On the annual support, 89 percent of the published zeros have a Copernicus D8 slope steeper than 0.5 degrees, and the median slope on those cells is 3.2 percent. Water, the nearest land-cover class, is 2.7 percent of the zeros. Cells that receive flow and have no downhill neighbour are 1.2 percent of the zeros, with a median accumulation of two cells. Cells with no downhill neighbour and no inflow are 40 percent. Cells with a positive downhill step are 56 percent. On that last group the median integer slope is 8 percent, a one-metre drop across 12.5 m, and 95 percent have an accumulation of one cell. The same one-metre step also occurs where published LS is positive, so the zero is not a slope cutoff at one metre.')
    add_table(doc, 'Table 15. Other annual scenarios. Means and medians are in t ha⁻¹ yr⁻¹. Gross volume is soil-loss mass divided by 1.45 t m⁻³, in million m³ yr⁻¹. Static K and the two standard-LS rows use 4,138,768 pixels. The radar and Renard–Freimund rows use the 4,154,545 twelve-month pixels. The downward cover and erosivity rows are in Table 13.', ['Case', 'Mean', 'Median', 'Gross volume'], [['Static K and published LS', '119', '20.4', '5.32'], ['Standard LS on integer-metre DEM', '103', '64', '4.60'], ['Standard LS on Copernicus GLO-30', '119', '62', '5.30'], ['Radar cover and Arnoldus', '87.2', '12.8', '3.90'], ['Linear cover and Renard–Freimund', '346', '53.4', '15.5']])
    body(doc, 'The rows in Table 15 keep the linear cover and an erosivity at or above the Arnoldus total, apart from the radar-cover row. Their means, 87 to 346 t ha⁻¹ yr⁻¹, sit above the Vanoni band of 51–75. Table 13 holds the replacements that lower C or R or raise P, and Table 14 tests each of them against the yield and against that band. The steepest-descent Copernicus rows remove most of the exact-zero LS values and leave the class above 100 at 35 percent. The unfilled multiple-flow grid is the terrain result: 1.0 percent exact zeros, 41 percent of the area above 100, median 72, and mean 140. That mean lies outside 51–75, with the other calculated means.')
    body(doc, 'The annual sum uses 4,154,545 pixels, 90.8 percent of the watershed. The other 421,649 watershed pixels lack at least one month (Figure 16 and Table 16). Their mean elevation is 411 m, against 388 m for the pixels in the annual sum, and their median elevation is 383 m against 366 m. The share of cells with D8 slope exactly zero is 38 percent in the annual set and 39 percent outside it. October NDVI has median 0.67 in both groups, and the annual cover factor has median 0.70 and 0.69. The exponential of an NDVI of 0.67 is 0.018, so the annual cover layer is not that transform of the October index. The excluded cells sit slightly higher on the plateau. Slope and vegetation are similar in the two groups. Monthly means in Table 6 still use the pixels valid in that month. The June–July comparison in Section 6.2 uses the annual support.')
    add_table(doc, 'Table 16. Pixels inside and outside the twelve-month annual sum. Elevation is in metres. NDVI is the October median. C is the annual cover factor.', ['Group', 'Pixels', 'Mean elevation', 'Median elevation', 'D8 slope zero', 'October NDVI', 'Annual C'], [['In the annual sum', '4,154,545', '388', '366', '38 percent', '0.67', '0.70'], ['Excluded', '421,649', '411', '383', '39 percent', '0.67', '0.69']])
    add_figure(doc, ((FIGURES / 'maps') / 'annual_support_mask.png'), 'Figure 16. Pixels used in the twelve-month annual sum, and watershed pixels excluded because at least one month is missing. The frame is WGS 84 / UTM zone 45N.')
    heading(doc, '6.6 Surrogate diagnostics of the multiplicative tail', 2)
    body(doc, 'Holdout diagnostics separate the architectures. The multilayer perceptron reproduces the multiplicative RUSLE surface, with R² = 0.920 and RMSE = 15.33 t ha⁻¹ yr⁻¹ (Table S1). XGBoost and Random Forest remain near R² = 0.45, at 0.451 and 0.443. The divergence is the tail above 100 t ha⁻¹ yr⁻¹. A tree returns a stored leaf and cannot pass the largest training value, 909 t ha⁻¹ yr⁻¹, while the holdout reaches 2,769. The perceptron is continuous in the same factors, so it follows the product past that leaf. CatBoost, the strongest tree, reaches R² = 0.548. The Reduced Integrated stack, which blends the four members, has R² = 0.832, RMSE = 22.19, and MAE = 1.02. The same ordering appears in the Dynamic Integrated set, where the perceptron has R² = 0.878 and the stack has R² = 0.702 (Table S2).')
    body(doc, 'The gap is in the class above 100 t ha⁻¹ yr⁻¹. That class, E6, has 27 holdout points, 0.7 percent of the holdout. On the Reduced Integrated stack their mean reference value is 334, their mean prediction is 270, their MAE is 74, and their RMSE is 263 (Table S3). Those 27 points supply 99.5 percent of the reduced-stack squared error. The largest training soil loss is 909 t ha⁻¹ yr⁻¹. The largest holdout soil loss is 2,769. Figures 17 and 18 show the stack against that tail. Table 17 gives the member scores in the main text. The same skew that separates the map mean of 136 t ha⁻¹ yr⁻¹ from the median of 21.7 t ha⁻¹ yr⁻¹ (Figure 14) is the tail these models are asked to reproduce. A tree partitions the predictors into leaves and returns a stored leaf value, so it cannot pass the largest training soil loss. The perceptron is continuous in the same factors, and because the RUSLE target is their product it can follow values past that training maximum. The scores recover a model-generated RUSLE surface on a random stratified holdout. They are not a test against observed sediment yield, and they were not used to change the maps.')
    add_table(doc, 'Table 17. Reduced Integrated holdout scores on 3,809 points. RMSE and MAE are in t ha⁻¹ yr⁻¹. In the class above 100 t ha⁻¹ yr⁻¹ the stack, not a single tree, has RMSE 263.', ['Model', 'R²', 'RMSE', 'MAE'], [['Multilayer perceptron', '0.920', '15.33', '1.01'], ['CatBoost', '0.548', '36.35', '1.47'], ['XGBoost', '0.451', '40.08', '1.76'], ['Random Forest', '0.443', '40.34', '1.94'], ['Stack', '0.832', '22.19', '1.02']])
    heading(doc, '7. Physical drivers, parameter sensitivity, and management implications', 1)
    body(doc, 'July contains about half of the linear-cover annual mean, so the month of erosion is identified. The size of the annual load is a separate result. Erosivity choices move that mean by about a factor of ten, and cover choices move it by about a factor of five. The live-storage loss of 1.01 million m³ yr⁻¹ is the benchmark that fixes a planning size. At a Vanoni delivery ratio of 0.20 the gross rate consistent with that loss is 51–75 t ha⁻¹ yr⁻¹. The Copernicus multiple-flow median of 72 lies in that band. The mean of 140 does not. The calibrated connectivity map, Figure 2, with IC₀ = −6.29, is the routing grid those scenarios pass through. The Vanoni, USDA, and Boyce curves remain the lumped check on that map. Section 6.6 shows why a continuous model follows the skewed tail of the same RUSLE surface while a tree stops at its training leaves. Those scores recover the model surface. They are not a sediment budget for Tilaiya Dam.')
    heading(doc, '7.1 What the scenarios can and cannot support', 2)
    body(doc, 'Within the linear-cover Arnoldus scenario, detachment is concentrated in the monsoon. The July mean is 65.4 t ha⁻¹, against 27.7 t ha⁻¹ in June and an annual mean of 136 t ha⁻¹ yr⁻¹, and the July median is 9.92 t ha⁻¹ against 4.65 t ha⁻¹ in June. That timing follows the monthly share of erosivity (Figure 13). Soil erodibility does not add a second seasonal pulse. Mean Km stays between 0.0393 and 0.0398 in every month of the reported maps. Stretching Sentinel-1 VV on the pooled 5th and 95th percentiles of 2025 raises July only to 0.0416, against 0.0387 in January, and the annual mean from 136 to 140 t ha⁻¹ yr⁻¹ (Section 6.2). The twelve months of 2025 are the full Sentinel-1 series available here. Their literal minimum and maximum leave January and July at 0.0392 and 0.0399. The 0.25° rainfall grid is also too coarse to site a farm pond.')
    body(doc, 'The annual mean of 136 t ha⁻¹ yr⁻¹ should be read with its distribution (Figure 14) and with the class map (Figure 12). The slope-length factor is exactly zero on 44 percent of the shared pixels, the median is 21.7 t ha⁻¹ yr⁻¹, 48 percent of the map falls in the 0–5 class, and 33 percent exceeds 100 t ha⁻¹ yr⁻¹. On the Copernicus GLO-30 surface, with multiple-flow Desmet–Govers slope length, the zero share falls to 1.0 percent, the median rises to 72 t ha⁻¹ yr⁻¹, and the mean is 140 t ha⁻¹ yr⁻¹ (Section 6.5). The earlier steepest-descent form of the same elevation has a median of 62 t ha⁻¹ yr⁻¹ and leaves 35 percent of the area above 100 (Table 15). A mean taken alone therefore misses both the artificial zero class of the published grid and the high tail that remains after that class is removed. Of the published zeros, 2.7 percent are water, 1.2 percent receive flow but have no downhill neighbour, 40 percent have neither inflow nor a downhill neighbour, and 56 percent still have a downhill step on the integer-metre elevation (Section 6.5). A priority flood of the same three satellite grids leaves means of 144, 136, and 136 t ha⁻¹ yr⁻¹ on ALOS, Copernicus, and SRTM. The ALOS fill raises no cell, and 38.5 percent of cells remain gentler than 0.5 degrees. Filling Copernicus and SRTM raises the flat share from 1.0 to 5.4 percent and from 2.5 to 15.1 percent. Filling ASTER GDEM, a Terra optical stereo surface and not a radar surface, raises the flat share from 1.2 to 23.7 percent and leaves a median of 117 and a mean of 220.')
    body(doc, 'The hydrologically reconciled consensus is 51–75 t ha⁻¹ yr⁻¹. That is the gross rate which supplies the recorded live-storage loss at a delivery ratio of 0.20. The connectivity grid at IC₀ = −6.29 has that unweighted mean ratio. The multiple-flow Copernicus map has a median of 72, inside that band, and a mean of 140 (Section 6.5). On that map the calibrated ratio delivers 1.35 million m³ yr⁻¹. The earlier steepest-descent form delivers 1.14 million m³ yr⁻¹. Linear cover at 136 is the uncalibrated upper bound. The adopted SAVI coefficient leaves cropland at 0.61 and vegetation at 0.51, above the published factors, so the equation assigns more of the bare-soil rate than those factors do. Exponential cover at 27.6 is the lower bound. Its coefficient was set for Europe and was not fitted here, and that curve places the catchment mean below the planning band of 51–75. The Boyce interval of 141–205 is the wider upper test. It contains the practice-factor mean of 182 and leaves 136 just below it (Table 14). Centering IC₀ on the median connectivity delivers 2.87 million m³ yr⁻¹ from the linear-cover map. That volume sits above the live-storage loss, and the mass-weighted ratio of 0.47 sits above the Vanoni ratio of 0.20 and the Boyce ratio of 0.073. Class shares rank the scenarios more sharply than those curves (Table 12). Linear cover places 60 percent of the mass on vegetation, one class that mixes forest, plantation, scrub and fallow, and 3.2 percent of the mass on barren land. The lookup places 23 percent of its mass on 2.2 percent barren land, which follows from a single cover of 0.005 on all vegetation and a cover of 1 on barren land. That geography is hard to defend. The exponential cover lies between those two patterns, with cropland carrying about half the mass. On cropland and vegetation, the exponential class means of 0.20 and 0.071 lie nearer the published cover factors than the linear means of 0.61 and 0.51 (Table 11). The linear scenario is the one above those benchmarks. The comparison leaves the mapped cover in place.')
    body(doc, 'Two measurements would narrow the window. The monthly erosivity surfaces of Das et al. (2025) would test the split of annual R by Pm²/ΣPm². Those surfaces were not obtained. They are available from the corresponding author on reasonable request. An HLS composite, or a Sentinel-2 composite with a relaxed cloud threshold, would replace the interpolated July and August NDVI (Claverie et al., 2018). July holds about half the annual mean, and a clear July scene covers 2.8 percent of the annual pixels. That composite was not calculated.')
    heading(doc, '7.2 Limits', 2)
    body(doc, 'The Arnoldus coefficients remain the Morocco calibration that Chen et al. (2023) defend, 17.02 and −0.8188. The India-grid value of 772 is a low-biased floor, and the Jharkhand average in that dataset is 1,198. Slope length on this plateau is sensitive to how elevation is stored. Integer-metre steps force the legacy factor to zero on 44.36 percent of the annual-support cells, and 56 percent of those zeros still have a downhill step. Continuous Copernicus GLO-30 elevations, routed by multiple flow and the Desmet and Govers factor, bring that zero share to 1.0 percent and the median soil loss to 72 t ha⁻¹ yr⁻¹. The mean remains 140 t ha⁻¹ yr⁻¹, because the steep cells stay in the map. A priority flood plus a 1 mm drainage step on ALOS, Copernicus, SRTM, and ASTER GDEM is the processing test in Section 6.5. On ASTER the flat share rises from 1.2 to 23.7 percent, the median is 117, and the mean is 220. That median lies above 51–75. That test leaves this unfilled Copernicus grid as the corrected terrain.  The aligned Sentinel-1 stack is the twelve months of 2025. An inventory of 2020–2025 finds those 12 months and 60 missing, so a multi-year envelope was not calculated. The 2025 extremes leave January and July mean Km at 0.0392 and 0.0399. Cover is tested as three formulations, linear SAVI, exponential NDVI, and a five-class lookup. The class map is the lookup scenario, and no accuracy is claimed for it. The area curves were not fitted at Tilaiya. The live-storage loss is a lower bound on sediment retained in the reservoir, because the survey omits dead storage. Sub-watershed 2A219 is ungauged for sediment. Section 6.6 records that the perceptron follows the multiplicative tail and the trees stop at the training maximum. Those scores recover the annual RUSLE surface on a random stratified holdout. They were not used to change the maps. The scripts, rasters, tables, metadata, and checksum inventory are deposited at https://github.com/mktiwari123/Tilaiya-2A219-soil-erosion-2025.')
    heading(doc, '8. Conclusions', 1)
    body(doc, 'Sub-watershed 2A219 is an ungauged monsoon headwater, and the 2025 soil-loss maps are RUSLE scenarios for that mask. Rainfall erosivity varies about tenfold, from the Arnoldus mask mean of 7,783 MJ mm ha⁻¹ h⁻¹ yr⁻¹ to a reanalysis floor of 772, and cover varies about fivefold, from the linear mean of 136 t ha⁻¹ yr⁻¹ to the means near 28. The primary terrain result is the unfilled Copernicus GLO-30 multiple-flow grid: the slope-length factor is exactly zero on 1.0 percent of the annual pixels, the soil-loss median is 72 t ha⁻¹ yr⁻¹, and the mean is 140 t ha⁻¹ yr⁻¹. The published slope-length factor is the legacy raster, exactly zero on 44.36 percent of the annual-support pixels, with a mean of 136 t ha⁻¹ yr⁻¹ and a median of 21.7 t ha⁻¹ yr⁻¹. The twelve monthly maps hold one slope-length grid, so month-to-month differences are erosivity and cover. The monthly series is the seasonal result on the legacy baseline, and the DEM comparison is a separate annual experiment. The monthly maps identify July as the peak month inside a scenario. They do not by themselves size the annual load that reached the reservoir. The reanalysis value of 772 is a low-biased floor. The Jharkhand average in that dataset is 1,198. Substituting the floor lowers the linear-cover mean to 12.9 t ha⁻¹ yr⁻¹, at the live-storage yield of 10–15 t ha⁻¹ yr⁻¹, and applying it together with exponential cover gives 2.88 t ha⁻¹ yr⁻¹, below that yield.')
    body(doc, 'The planning target is 51–75 t ha⁻¹ yr⁻¹. That is the gross hillslope rate which supplies the recorded live-storage loss of 1.01 million m³ yr⁻¹ at a Vanoni delivery ratio of 0.20. Linear cover on the published grid, 136 t ha⁻¹ yr⁻¹, is the uncalibrated upper bound, and exponential cover, 27.6 t ha⁻¹ yr⁻¹, is the lower bound. The multiple-flow Copernicus median of 72 t ha⁻¹ yr⁻¹ lies in that band. The mean of 140 t ha⁻¹ yr⁻¹ does not. No calculated mean falls inside 51–75, and no flat 51–75 surface was mapped. Copernicus was chosen because the unfilled surface is flat on 1.0 percent of cells and the fill raises only 4.8 percent. ALOS plateaus stay 38.5 percent flat. The SRTM fill raises the flat share to 15.1 percent. The ASTER fill raises the flat share to 23.7 percent and the mean becomes 220. After a priority flood and a 1 mm drainage step, the ALOS, Copernicus, and SRTM means stay near 136–144, with medians 94, 68, and 77 t ha⁻¹ yr⁻¹. The unfilled Copernicus multiple-flow grid remains the terrain result. The earlier steepest-descent form has a median of 62 and a mean of 119. The Boyce curve widens the admissible range to 141–205 t ha⁻¹ yr⁻¹, which contains the support-practice mean of 182 and leaves 136 just below it. Setting the connectivity threshold to the median index delivers 2.87 million m³ yr⁻¹ from the linear-cover map, above the live-storage loss. Setting it so the unweighted mean delivery ratio equals 0.20 delivers 1.61 million m³ yr⁻¹. That equality is the choice of threshold. The ranking of paths is the connectivity index, and the paths end at the catchment outlet.')
    body(doc, 'Vegetation carries 60 percent of the linear-cover mass from 40 percent of the area. The five-class lookup places 23 percent of its mass on barren land, which is 2.2 percent of the area. On cropland and vegetation the exponential class means, 0.20 and 0.071, lie nearer the published cover factors than the linear means of 0.61 and 0.51. On the 3,809-point holdout the perceptron reaches R² = 0.920, while XGBoost and Random Forest stay at 0.451 and 0.443. In the class above 100 t ha⁻¹ yr⁻¹ the stack RMSE is 263 t ha⁻¹ yr⁻¹, because a tree cannot leave the training maximum of 909 t ha⁻¹ yr⁻¹ and the holdout reaches 2,769 t ha⁻¹ yr⁻¹. The full member tables are in the supplement.')
    body(doc, 'Sub-watershed 2A219 is ungauged for sediment. The published sediment records describe Karso, Banha, earlier Tilaiya streamflow, or reservoir storage for the whole dam, so the 2025 maps for this mask are soil-loss scenarios from rainfall, satellite cover, soil grids, and elevation. Section 6.6 and the supplement tables are surrogate-model diagnostics from a random stratified holdout, with spatial blocks used inside training. The scripts, rasters, tables, metadata, and checksum inventory are deposited at https://github.com/mktiwari123/Tilaiya-2A219-soil-erosion-2025.')
    heading(doc, 'Supplement. Stacking diagnostics', 1)
    body(doc, 'This supplement reports how closely a stack reproduces the annual RUSLE surface and which factors the XGBoost members use. The holdout is a random stratified split. The 2025 soil-loss maps were left unchanged.')
    heading(doc, 'S1. Surrogate recovery of the annual RUSLE surface', 2)
    body(doc, 'On the 3,809 holdout points, the Reduced Integrated stack has R² = 0.832, RMSE = 22.19 t ha⁻¹ yr⁻¹, and MAE = 1.02 t ha⁻¹ yr⁻¹ (Table S1). Out-of-fold performance on the 8,888 training points is much higher (R² = 0.983, RMSE = 2.96, MAE = 0.71). The stack recovers the annual RUSLE surface from its own factors. The target is that model-generated value, and the predictors include factors of the same surface, so the scores measure how well the learners reproduce the reference estimate. They are not a test against sediment. The holdout is a random stratified split. The multilayer perceptron alone has holdout R² = 0.920, RMSE = 15.33, and MAE = 1.01. CatBoost, XGBoost, and Random Forest are weaker as single models (holdout R² 0.548, 0.451, and 0.443). The 27 holdout points with a reference RUSLE value above 100 t ha⁻¹ yr⁻¹, 0.7 percent of the holdout, supply 99.5 percent of the reduced-stack squared error and 98.1 percent of the dynamic-stack squared error. Tree predictions stay within the training maximum of 909 t ha⁻¹ yr⁻¹, while the holdout reaches 2,769. The holdout points were drawn at random inside the watershed, so neighbouring cells can fall on opposite sides of the split (Roberts et al., 2017; Ploton et al., 2020). The reported scores refer to this random stratified holdout. Ridge weights on the blend are CatBoost 0.702, perceptron 0.567, XGBoost −0.085, and Random Forest −0.167, with intercept −0.097.')
    body(doc, 'Holdout MAE near 1 t ha⁻¹ yr⁻¹ means that a typical point is close to the RUSLE value. Holdout RMSE is large because the test set contains the extreme tail. The largest training soil loss is 909 t ha⁻¹ yr⁻¹. The largest holdout soil loss is 2,769 t ha⁻¹ yr⁻¹. Three holdout points exceed 500 t ha⁻¹ yr⁻¹, and 27 exceed 100 t ha⁻¹ yr⁻¹. The stack under-predicts the most extreme points. Figure 17 shows the reference RUSLE value against the stack prediction for the Reduced Integrated model. Figure 18 shows the same comparison for the Dynamic Integrated model.')
    add_table(doc, 'Table S1. Reduced Integrated models. Predictors are LS, SOC, C, P, NDVI, and K. RMSE and MAE are in t ha⁻¹ yr⁻¹. The holdout has 3,809 points.', ['Model', 'Set', 'R²', 'RMSE', 'MAE'], [['Stack, out of fold', 'Training blocks', '0.983', '2.96', '0.71'], ['Stack', 'Holdout', '0.832', '22.19', '1.02'], ['Multilayer perceptron', 'Holdout', '0.920', '15.33', '1.01'], ['CatBoost', 'Holdout', '0.548', '36.35', '1.47'], ['XGBoost', 'Holdout', '0.451', '40.08', '1.76'], ['Random Forest', 'Holdout', '0.443', '40.34', '1.94']])
    add_figure(doc, ((FIGURES / 'Reduced_Integrated') / 'observed_vs_predicted.png'), 'Figure 17. Reference annual RUSLE estimate against the Reduced Integrated stack on the holdout. The squared error is dominated by a small number of very large reference values. The vertical axis is the model-generated RUSLE surface.')
    add_figure(doc, ((FIGURES / 'Dynamic_Integrated') / 'observed_vs_predicted.png'), 'Figure 18. Reference annual RUSLE estimate against the Dynamic Integrated stack on the same holdout points. Holdout R² is 0.702. The target is the annual RUSLE layer.')
    body(doc, 'Dynamic Integrated has holdout R² = 0.702, RMSE = 29.49, and MAE = 1.77 on the same annual RUSLE target (Table S2). Its perceptron member again fits the holdout more closely than the blend (R² = 0.878, RMSE = 18.90). Ridge weights are CatBoost 0.903, perceptron 0.389, XGBoost 0.042, and Random Forest −0.282, with intercept −0.295. This comparison changes both the predictors and their relationship to the target, because the target was calculated with annual K and C, while the second stack uses R, Kₘ, Cₘ, RVI, and SAVI instead of K, C, and NDVI. The lower score describes compatibility with that annual target. A comparison that predicts the 2025 monthly maps, the dynamic annual sum, or measured sediment remains for later work.')
    add_table(doc, 'Table S2. Dynamic Integrated models. Predictors are LS, R, Kₘ, Cₘ, P, RVI, SAVI, and SOC. RMSE and MAE are in t ha⁻¹ yr⁻¹.', ['Model', 'Set', 'R²', 'RMSE', 'MAE'], [['Stack, out of fold', 'Training blocks', '0.964', '4.31', '1.20'], ['Stack', 'Holdout', '0.702', '29.49', '1.77'], ['Multilayer perceptron', 'Holdout', '0.878', '18.90', '2.01'], ['CatBoost', 'Holdout', '0.466', '39.52', '1.65'], ['XGBoost', 'Holdout', '0.411', '41.51', '1.86'], ['Random Forest', 'Holdout', '0.390', '42.22', '2.55']])
    body(doc, 'Holdout error differs across the erosion classes (Table S3). For the Reduced Integrated stack, MAE is 0.37 t ha-1 yr-1 in E1 (n = 2,319) and rises only to 2.46 in E5 (n = 74). In E6, the 27 points above 100 t ha-1 yr-1, MAE is 74 and RMSE is 263. Their mean reference RUSLE value is 334 and the mean prediction is 270. Dynamic Integrated shows the same pattern, with E6 MAE 113. The aggregate RMSE therefore comes from the extreme class. The perceptron holdout R² is 0.920, against 0.451 for XGBoost and 0.443 for Random Forest. A tree prediction stays inside the training leaves, whose largest soil-loss value is 909 t ha⁻¹ yr⁻¹, while the holdout reaches 2,769. The 27 points above 100 t ha⁻¹ yr⁻¹ have an RMSE of 263. The perceptron is a continuous function of the same factors and can follow reference values past that training maximum. On this holdout, that is why the neural member recovers the multiplicative RUSLE surface more closely than the trees. The scores still recover a model-generated target. They are not a test against reservoir sediment. One random seed and one stratified holdout were used. The holdout is a random stratified split. Spatial blocks were used inside training, and the reported R² describes that holdout.')
    add_table(doc, 'Table S3. Reduced Integrated holdout error by annual RUSLE class. MAE and RMSE are in t ha-1 yr-1.', ['Class', 'n', 'Mean reference', 'Mean predicted', 'MAE', 'RMSE'], [['E1, 0-5', '2,319', '0.63', '0.63', '0.37', '1.67'], ['E2, 5-15', '862', '9.24', '9.29', '0.42', '0.86'], ['E3, 15-30', '390', '20.8', '20.9', '0.75', '1.12'], ['E4, 30-50', '137', '37.1', '37.5', '1.38', '2.35'], ['E5, 50-100', '74', '64.9', '65.9', '2.46', '3.09'], ['E6, above 100', '27', '334', '270', '74.0', '263']])
    heading(doc, 'S2. Attributions inside the XGBoost members', 2)
    body(doc, 'Mean absolute SHAP on the Reduced Integrated XGBoost model attributes the largest share to LS. The unrounded value is 10.326 t ha⁻¹ yr⁻¹, then P (2.686), SOC (2.347), K (0.983), C (0.493), and NDVI (0.105) (Table S4 and Figures 19–22). The Dynamic Integrated file, from a separate run, gives LS 10.329. The two numbers round to 10.33. They differ by 0.003 because both models see the same LS-dominated target. Values of LS, P, C, and K above the holdout median increase predicted soil loss. Values of SOC above the median decrease it. NDVI has little separate effect once C is in the model. The aligned annual C layer has a minimum of 0.284 across the watershed, so holdout C stays at or above that minimum. The attribution explains the XGBoost member and the model-derived RUSLE target. LS is also a factor of the RUSLE target, so a large LS attribution partly recovers that construction. The attribution refers to this holdout.')
    add_table(doc, 'Table S4. Mean absolute SHAP for the Reduced Integrated XGBoost member on 3,809 holdout points. Values are model attributions for the XGBoost member.', ['Feature', 'Mean absolute SHAP (t ha⁻¹ yr⁻¹)'], [['LS', '10.326'], ['P', '2.69'], ['SOC', '2.35'], ['K', '0.98'], ['C', '0.49'], ['NDVI', '0.11']])
    add_figure(doc, (((FIGURES / 'Reduced_Integrated') / 'shap') / 'shap_summary.png'), 'Figure 19. TreeSHAP summary for the Reduced Integrated XGBoost model on the holdout. Each point is one holdout location. LS dominates the spread of predicted soil loss.')
    add_figure(doc, (((FIGURES / 'Reduced_Integrated') / 'shap') / 'shap_importance.png'), 'Figure 20. Mean absolute SHAP for the Reduced Integrated XGBoost member. The values are attributions for that member.')
    add_figure(doc, (((FIGURES / 'Reduced_Integrated') / 'shap') / 'shap_dependence_LS.png'), 'Figure 21. SHAP dependence on the LS factor for the Reduced Integrated XGBoost member. Higher LS increases predicted soil loss.')
    add_figure(doc, (((FIGURES / 'Reduced_Integrated') / 'shap') / 'shap_dependence_C.png'), 'Figure 22. SHAP dependence on annual cover for the Reduced Integrated XGBoost member. No holdout point has annual C below 0.15.')
    body(doc, 'The same holdout, explained for the Dynamic Integrated XGBoost model, keeps LS first. The unrounded mean absolute SHAP is 10.329 t ha⁻¹ yr⁻¹, against 10.326 in the Reduced Integrated file (Table S5 and Figures 23–26). Support practice remains second (2.59). The within-month stretch Km is third (2.04), ahead of SOC (1.44). SAVI (0.37) and Cm (0.22) are small. Rainfall erosivity R (0.07) and RVI (0.06) add almost nothing. Values above the holdout median increase predicted loss for LS, P, Km, and Cm, and decrease it for SOC and SAVI. The sign on Cm matches the RUSLE cover factor: a higher Cm is less protection. The sign on SAVI runs the other way, as expected for a vegetation index. No holdout point has Cm below 0.15. The mean holdout Cm is 0.577, while the watershed July map reaches the cover floor. This ranking describes the Dynamic XGBoost member.')
    add_table(doc, 'Table S5. Mean absolute SHAP for the Dynamic Integrated XGBoost member on the same 3,809 holdout points. Values are model attributions for the XGBoost member.', ['Feature', 'Mean absolute SHAP (t ha⁻¹ yr⁻¹)'], [['LS', '10.329'], ['P', '2.59'], ['Km', '2.04'], ['SOC', '1.44'], ['SAVI', '0.37'], ['Cm', '0.22'], ['R', '0.07'], ['RVI', '0.06']])
    add_figure(doc, (((FIGURES / 'Dynamic_Integrated') / 'shap') / 'shap_summary.png'), 'Figure 23. TreeSHAP summary for the Dynamic Integrated XGBoost model on the holdout. The LS factor remains dominant. Monthly erosivity and RVI contribute little at the sample points.')
    add_figure(doc, (((FIGURES / 'Dynamic_Integrated') / 'shap') / 'shap_importance.png'), 'Figure 24. Mean absolute SHAP for the Dynamic Integrated XGBoost member. Km ranks third. R and RVI are the smallest terms.')
    add_figure(doc, (((FIGURES / 'Dynamic_Integrated') / 'shap') / 'shap_dependence_LS.png'), 'Figure 25. SHAP dependence on the LS factor for the Dynamic Integrated XGBoost member. The pattern follows the same LS-dominated target as Figure 21.')
    add_figure(doc, (((FIGURES / 'Dynamic_Integrated') / 'shap') / 'shap_dependence_Cm.png'), 'Figure 26. SHAP dependence on mean monthly cover for the Dynamic Integrated XGBoost member. No holdout point has Cm below 0.15.')
    heading(doc, 'S3. What the stacking scores mean', 2)
    body(doc, 'Section S1 shows how closely a stack emulates the annual RUSLE surface from the factors of that surface. The R², RMSE, and MAE values are surrogate-model diagnostics. The holdout is a random stratified split, with spatial blocks used inside training. The 2025 soil-loss maps were left unchanged.')
    heading(doc, 'S4. SHAP attributions', 2)
    body(doc, 'Section S2 gives the XGBoost attributions. They explain that member and the model-derived target. LS leads both files because LS is also a factor of the target. A high rank for Km can follow slope or aspect, because Km is a within-month stretch of Sentinel-1 backscatter.')
    heading(doc, 'CRediT authorship contribution statement', 1)
    body(doc, 'Mukesh Kumar Tiwari: conceptualisation, methodology, software, formal analysis, visualisation, writing — original draft. Prabhat Kumar Guru: writing — review and editing.', first_line=False)
    heading(doc, 'Declaration of competing interest', 1)
    body(doc, 'The authors declare that they have no known competing financial interests or personal relationships that could have appeared to influence the work reported in this paper.', first_line=False)
    heading(doc, 'Data availability', 1)
    body(doc, 'Sentinel-1 and Sentinel-2 scenes are the public Copernicus collections COPERNICUS/S1_GRD and COPERNICUS/S2_SR_HARMONIZED. IMD daily rainfall grids and SoilGrids layers are public. The analysis scripts, scenario tables, soil-loss rasters, metadata, and checksum inventory are deposited at https://github.com/mktiwari123/Tilaiya-2A219-soil-erosion-2025. The stacking holdout is a random stratified split, with spatial blocks used inside training. The annual baseline rasters used as static inputs were left unchanged.', first_line=False)
    heading(doc, 'Acknowledgements', 1)
    body(doc, 'The India Meteorological Department daily gridded rainfall, Copernicus Sentinel-1 and Sentinel-2 data, the ALOS PALSAR digital elevation model, ISRIC SoilGrids, and the Damodar Valley Corporation reservoir summary made this analysis possible.', first_line=False)
